-- =============================================================================
-- schema.sql · Full DDL snapshot — IIUI Schools & College, Mardan Campus
-- Generated by concatenating database/migrations/0000 through 0013 in order.
-- This file is a REFERENCE snapshot for quick one-shot import; the numbered
-- files in database/migrations/ remain the source of truth and run order.
-- =============================================================================


-- ============================== 0000_init.sql ==============================

-- =============================================================================
-- IIUI Schools & College – Mardan Campus
-- 0000_init.sql  ·  Database creation + migration tracking
-- -----------------------------------------------------------------------------
-- Target      : MySQL 8.0+ / MariaDB 10.4+   (installed: MariaDB 10.4.32)
-- Engine      : InnoDB      Charset: utf8mb4      Collation: utf8mb4_unicode_ci
-- Run order   : 0000 → 0014, in sequence. Files 0012–0014 (views, triggers,
--               procedures) require the mysql client because they use DELIMITER.
-- -----------------------------------------------------------------------------
--
--  ENTITY RELATIONSHIP OVERVIEW
--
--  ┌───────────────────────── A. IDENTITY & ACCESS ─────────────────────────┐
--  │  users ─┬─< user_roles >─ roles ─< role_permissions >─ permissions     │
--  │         ├─< user_permissions >──────────────────────────┘              │
--  │         ├─< user_sessions   ├─< personal_access_tokens                 │
--  │         └─< audit_logs                                                 │
--  └────────────────────────────────────────────────────────────────────────┘
--        │ 1:0..1                │ 1:0..1              │ 1:0..1
--        ▼                       ▼                     ▼
--    students                  staff                guardians
--
--  ┌────────────────────── B. ACADEMIC STRUCTURE ───────────────────────────┐
--  │  campuses ─< school_classes ─┬─< sections ────────────┐                │
--  │                              ├─< class_streams >─ streams              │
--  │                              └─< class_subjects >─ subjects            │
--  │  academic_sessions ──scopes──> sections, class_subjects, enrollments,  │
--  │                                attendance, exams, challans, timetables │
--  │  grade_scales · holidays · timetables                                  │
--  └────────────────────────────────────────────────────────────────────────┘
--
--  ┌────────────────── C. STUDENTS ──────────────┐  ┌──── D. STAFF ─────────┐
--  │ admission_applications ──converts──> students│  │ departments           │
--  │ students ─┬─< student_enrollments (1/session)│  │ designations          │
--  │           ├─< student_guardians >─ guardians │  │ staff ─┬─< staff_subj │
--  │           ├─< student_documents              │  │        ├─< staff_docs │
--  │           ├─< student_promotions             │  │        └─< payrolls   │
--  │           └─< student_transfers              │  └───────────────────────┘
--  └──────────────────────────────────────────────┘
--                  │                                        │
--  ┌──── E. ATTENDANCE ────┐  ┌──── F. EXAMINATION ────┐  ┌── G. FINANCE ───┐
--  │ student_attendance    │  │ exam_terms ─< exams    │  │ fee_categories  │
--  │   UQ(student,date)    │  │   exams ─< marks       │  │ fee_structures  │
--  │ staff_attendance      │  │   UQ(exam,student)     │  │ fee_challans    │
--  │ leave_applications    │  │ result_summaries       │  │  ├─< items      │
--  │ holidays              │  │ datesheets             │  │  ├─< payments   │
--  └───────────────────────┘  │ exam_attendance        │  │  └─< fines      │
--                             └────────────────────────┘  │ expenses        │
--                                                         │ transactions    │
--  ┌──────── H. CMS ────────┐  ┌── I. COMMS ──┐           └─────────────────┘
--  │ pages · posts · tags   │  │ notifications │  ┌─── J. OPTIONAL ─────────┐
--  │ events · notices       │  │ messages      │  │ books ─< book_issues    │
--  │ galleries ─< images    │  │ email_*       │  │ transport_routes        │
--  │ menus ─< menu_items    │  │ sms_*         │  │   ├─< route_stops       │
--  │ media · settings · seo │  └───────────────┘  │   └─< student_transport │
--  └────────────────────────┘                     └─────────────────────────┘
--
--  DELETE-RULE POLICY
--    RESTRICT  → academic + financial history (enrollments, marks, payments)
--    CASCADE   → true composition only (challan items, gallery images, pivots)
--    SET NULL  → optional references (author_id, class_teacher_id)
--    Business "delete" is soft delete (deleted_at), never DDL removal.
-- =============================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET @OLD_SQL_MODE = @@SQL_MODE;
SET SQL_MODE = 'STRICT_ALL_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';

CREATE DATABASE IF NOT EXISTS `iiui_mardan`
    DEFAULT CHARACTER SET utf8mb4
    DEFAULT COLLATE utf8mb4_unicode_ci;

USE `iiui_mardan`;

-- -----------------------------------------------------------------------------
-- Migration tracking — every file below records itself here on success.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `migrations` (
    `id`         INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `filename`   VARCHAR(191) NOT NULL,
    `batch`      INT UNSIGNED NOT NULL DEFAULT 1,
    `checksum`   CHAR(64)     NULL,
    `applied_at` TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_migrations_filename` (`filename`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

INSERT INTO `migrations` (`filename`, `batch`) VALUES ('0000_init.sql', 1)
    ON DUPLICATE KEY UPDATE `applied_at` = `applied_at`;

SET FOREIGN_KEY_CHECKS = 1;

-- ============================== 0001_identity_and_access.sql ==============================

-- =============================================================================
-- 0001_identity_and_access.sql  ·  Domain A — Identity, RBAC, sessions, audit
-- =============================================================================
USE `iiui_mardan`;
SET FOREIGN_KEY_CHECKS = 0;

-- -----------------------------------------------------------------------------
-- users — the login identity, deliberately separate from students/staff/guardians
-- so one person may hold several profiles (parent AND teacher), and a young
-- student may exist with no login at all.
-- -----------------------------------------------------------------------------
CREATE TABLE `users` (
    `id`                    BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `uuid`                  CHAR(36)        NOT NULL,
    `username`              VARCHAR(60)     NOT NULL,
    `email`                 VARCHAR(191)    NULL,
    `phone`                 VARCHAR(20)     NULL,
    `password_hash`         VARCHAR(255)    NOT NULL,
    `first_name`            VARCHAR(80)     NOT NULL,
    `last_name`             VARCHAR(80)     NULL,
    `avatar`                VARCHAR(255)    NULL,
    `status`                ENUM('active','inactive','suspended','pending') NOT NULL DEFAULT 'pending',
    `email_verified_at`     TIMESTAMP       NULL DEFAULT NULL,
    `must_change_password`  TINYINT(1)      NOT NULL DEFAULT 1,
    `two_factor_secret`     VARBINARY(255)  NULL,
    `two_factor_enabled`    TINYINT(1)      NOT NULL DEFAULT 0,
    `two_factor_recovery`   TEXT            NULL,
    `last_login_at`         TIMESTAMP       NULL DEFAULT NULL,
    `last_login_ip`         VARBINARY(16)   NULL,
    `failed_attempts`       SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    `locked_until`          TIMESTAMP       NULL DEFAULT NULL,
    `password_changed_at`   TIMESTAMP       NULL DEFAULT NULL,
    `remember_token`        CHAR(64)        NULL,
    `locale`                CHAR(5)         NOT NULL DEFAULT 'en',
    `theme`                 ENUM('light','dark','system') NOT NULL DEFAULT 'system',
    `created_by`            BIGINT UNSIGNED NULL,
    `updated_by`            BIGINT UNSIGNED NULL,
    `created_at`            TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`            TIMESTAMP       NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    `deleted_at`            TIMESTAMP       NULL DEFAULT NULL,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_users_uuid`     (`uuid`),
    UNIQUE KEY `uq_users_username` (`username`),
    UNIQUE KEY `uq_users_email`    (`email`),
    KEY `idx_users_status_deleted` (`status`, `deleted_at`),
    KEY `idx_users_phone`          (`phone`),
    KEY `idx_users_last_login`     (`last_login_at`),
    CONSTRAINT `fk_users_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_users_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- roles — `level` is a hierarchy rank; a user may never assign a role at or
-- above their own level (enforced in the service layer, documented here).
-- -----------------------------------------------------------------------------
CREATE TABLE `roles` (
    `id`          SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `slug`        VARCHAR(50)  NOT NULL,
    `name`        VARCHAR(80)  NOT NULL,
    `description` VARCHAR(255) NULL,
    `level`       TINYINT UNSIGNED NOT NULL DEFAULT 10,
    `is_system`   TINYINT(1)   NOT NULL DEFAULT 0,
    `created_at`  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`  TIMESTAMP    NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_roles_slug` (`slug`),
    KEY `idx_roles_level` (`level`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- permissions — slug format is strictly `module.action` (students.create, fees.collect)
CREATE TABLE `permissions` (
    `id`          SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `slug`        VARCHAR(80) NOT NULL,
    `name`        VARCHAR(120) NOT NULL,
    `module`      VARCHAR(50)  NOT NULL,
    `group_name`  VARCHAR(50)  NULL,
    `created_at`  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_permissions_slug` (`slug`),
    KEY `idx_permissions_module` (`module`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `role_permissions` (
    `role_id`       SMALLINT UNSIGNED NOT NULL,
    `permission_id` SMALLINT UNSIGNED NOT NULL,
    PRIMARY KEY (`role_id`, `permission_id`),
    KEY `idx_role_permissions_permission` (`permission_id`),
    CONSTRAINT `fk_role_permissions_role`       FOREIGN KEY (`role_id`)       REFERENCES `roles` (`id`)       ON DELETE CASCADE,
    CONSTRAINT `fk_role_permissions_permission` FOREIGN KEY (`permission_id`) REFERENCES `permissions` (`id`) ON DELETE CASCADE
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `user_roles` (
    `user_id`     BIGINT UNSIGNED   NOT NULL,
    `role_id`     SMALLINT UNSIGNED NOT NULL,
    `assigned_by` BIGINT UNSIGNED   NULL,
    `assigned_at` TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`user_id`, `role_id`),
    KEY `idx_user_roles_role` (`role_id`),
    CONSTRAINT `fk_user_roles_user`        FOREIGN KEY (`user_id`)     REFERENCES `users` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_user_roles_role`        FOREIGN KEY (`role_id`)     REFERENCES `roles` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_user_roles_assigned_by` FOREIGN KEY (`assigned_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- user_permissions — per-user override. type='deny' always wins over any role grant.
CREATE TABLE `user_permissions` (
    `user_id`       BIGINT UNSIGNED   NOT NULL,
    `permission_id` SMALLINT UNSIGNED NOT NULL,
    `type`          ENUM('grant','deny') NOT NULL DEFAULT 'grant',
    `granted_by`    BIGINT UNSIGNED   NULL,
    `reason`        VARCHAR(255)      NULL,
    `created_at`    TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`user_id`, `permission_id`),
    KEY `idx_user_permissions_permission` (`permission_id`),
    CONSTRAINT `fk_user_permissions_user`       FOREIGN KEY (`user_id`)       REFERENCES `users` (`id`)       ON DELETE CASCADE,
    CONSTRAINT `fk_user_permissions_permission` FOREIGN KEY (`permission_id`) REFERENCES `permissions` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_user_permissions_granted_by` FOREIGN KEY (`granted_by`)    REFERENCES `users` (`id`)       ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- Security operations tables
-- -----------------------------------------------------------------------------
CREATE TABLE `password_resets` (
    `id`         BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `email`      VARCHAR(191) NOT NULL,
    `token_hash` CHAR(64)     NOT NULL,
    `ip_address` VARBINARY(16) NULL,
    `expires_at` TIMESTAMP    NOT NULL,
    `used_at`    TIMESTAMP    NULL DEFAULT NULL,
    `created_at` TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_password_resets_token` (`token_hash`),
    KEY `idx_password_resets_email_expiry` (`email`, `expires_at`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- login_attempts — the source of truth for throttling and lockout decisions.
CREATE TABLE `login_attempts` (
    `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `identifier`     VARCHAR(191)  NOT NULL,
    `ip_address`     VARBINARY(16) NOT NULL,
    `user_agent`     VARCHAR(255)  NULL,
    `was_successful` TINYINT(1)    NOT NULL DEFAULT 0,
    `failure_reason` VARCHAR(60)   NULL,
    `attempted_at`   TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_login_attempts_identifier` (`identifier`, `attempted_at`),
    KEY `idx_login_attempts_ip`         (`ip_address`, `attempted_at`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- user_sessions — enables the "log out all other devices" control.
CREATE TABLE `user_sessions` (
    `id`            CHAR(64)        NOT NULL,
    `user_id`       BIGINT UNSIGNED NULL,
    `ip_address`    VARBINARY(16)   NULL,
    `user_agent`    VARCHAR(255)    NULL,
    `fingerprint`   CHAR(64)        NULL,
    `payload`       MEDIUMTEXT      NULL,
    `last_activity` INT UNSIGNED    NOT NULL,
    `created_at`    TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_user_sessions_user`     (`user_id`),
    KEY `idx_user_sessions_activity` (`last_activity`),
    CONSTRAINT `fk_user_sessions_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `personal_access_tokens` (
    `id`           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `user_id`      BIGINT UNSIGNED NOT NULL,
    `name`         VARCHAR(100)    NOT NULL,
    `token_hash`   CHAR(64)        NOT NULL,
    `abilities`    JSON            NULL,
    `last_used_at` TIMESTAMP       NULL DEFAULT NULL,
    `expires_at`   TIMESTAMP       NULL DEFAULT NULL,
    `revoked_at`   TIMESTAMP       NULL DEFAULT NULL,
    `created_at`   TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_pat_token` (`token_hash`),
    KEY `idx_pat_user` (`user_id`, `revoked_at`),
    CONSTRAINT `fk_pat_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- audit_logs — append-only. No application path updates or deletes these rows;
-- the app's DB user is granted INSERT/SELECT here only.
-- -----------------------------------------------------------------------------
CREATE TABLE `audit_logs` (
    `id`          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `user_id`     BIGINT UNSIGNED NULL,
    `action`      VARCHAR(60)     NOT NULL,
    `module`      VARCHAR(50)     NULL,
    `entity_type` VARCHAR(80)     NULL,
    `entity_id`   BIGINT UNSIGNED NULL,
    `description` VARCHAR(255)    NULL,
    `old_values`  JSON            NULL,
    `new_values`  JSON            NULL,
    `ip_address`  VARBINARY(16)   NULL,
    `user_agent`  VARCHAR(255)    NULL,
    `request_id`  CHAR(36)        NULL,
    `created_at`  TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_audit_logs_entity` (`entity_type`, `entity_id`),
    KEY `idx_audit_logs_user`   (`user_id`, `created_at`),
    KEY `idx_audit_logs_action` (`action`, `created_at`),
    KEY `idx_audit_logs_module` (`module`, `created_at`),
    CONSTRAINT `fk_audit_logs_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
INSERT INTO `migrations` (`filename`, `batch`) VALUES ('0001_identity_and_access.sql', 1);

-- ============================== 0002_academic_structure.sql ==============================

-- =============================================================================
-- 0002_academic_structure.sql  ·  Domain B — Sessions, classes, subjects, grading
-- -----------------------------------------------------------------------------
-- Foreign keys pointing at `staff` (class_teacher_id, teacher_id) are added in
-- 0004 once that table exists — see the deferred ALTER block there.
-- =============================================================================
USE `iiui_mardan`;
SET FOREIGN_KEY_CHECKS = 0;

-- -----------------------------------------------------------------------------
-- academic_sessions — the spine of the whole schema.
-- `is_current_key` is a STORED generated column that is 1 when the session is
-- current and NULL otherwise. Because NULLs never collide in a UNIQUE index,
-- this makes "exactly one current session" a database-level guarantee rather
-- than an application convention.
-- -----------------------------------------------------------------------------
CREATE TABLE `academic_sessions` (
    `id`             SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `name`           VARCHAR(20)  NOT NULL COMMENT 'e.g. 2026-2027',
    `code`           VARCHAR(12)  NOT NULL,
    `start_date`     DATE         NOT NULL,
    `end_date`       DATE         NOT NULL,
    `is_current`     TINYINT(1)   NOT NULL DEFAULT 0,
    `is_current_key` TINYINT(1)   GENERATED ALWAYS AS (CASE WHEN `is_current` = 1 THEN 1 ELSE NULL END) STORED,
    `status`         ENUM('upcoming','active','closed') NOT NULL DEFAULT 'upcoming',
    `closed_at`      TIMESTAMP    NULL DEFAULT NULL,
    `closed_by`      BIGINT UNSIGNED NULL,
    `created_at`     TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`     TIMESTAMP    NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_academic_sessions_name`    (`name`),
    UNIQUE KEY `uq_academic_sessions_code`    (`code`),
    UNIQUE KEY `uq_academic_sessions_current` (`is_current_key`),
    KEY `idx_academic_sessions_dates` (`start_date`, `end_date`),
    CONSTRAINT `chk_academic_sessions_dates` CHECK (`end_date` > `start_date`),
    CONSTRAINT `fk_academic_sessions_closed_by` FOREIGN KEY (`closed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- campuses — one row today; the seam for multi-campus expansion.
CREATE TABLE `campuses` (
    `id`         TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `name`       VARCHAR(120) NOT NULL,
    `code`       VARCHAR(10)  NOT NULL,
    `address`    VARCHAR(255) NULL,
    `city`       VARCHAR(60)  NULL,
    `phone`      VARCHAR(20)  NULL,
    `email`      VARCHAR(191) NULL,
    `is_active`  TINYINT(1)   NOT NULL DEFAULT 1,
    `created_at` TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP    NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_campuses_code` (`code`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- school_classes — named `school_classes`, never `classes`: `class` collides with
-- reserved words in ORMs and reads ambiguously in SQL.
CREATE TABLE `school_classes` (
    `id`            SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `campus_id`     TINYINT UNSIGNED  NOT NULL DEFAULT 1,
    `name`          VARCHAR(40)  NOT NULL COMMENT 'e.g. Class 9',
    `short_name`    VARCHAR(12)  NULL,
    `numeric_level` TINYINT UNSIGNED NOT NULL COMMENT 'ordering + promotion path',
    `wing`          ENUM('primary','middle','secondary','college') NOT NULL DEFAULT 'secondary',
    `sort_order`    SMALLINT     NOT NULL DEFAULT 0,
    `is_active`     TINYINT(1)   NOT NULL DEFAULT 1,
    `created_at`    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`    TIMESTAMP    NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_school_classes_campus_name` (`campus_id`, `name`),
    KEY `idx_school_classes_level` (`numeric_level`),
    KEY `idx_school_classes_wing`  (`wing`, `is_active`),
    CONSTRAINT `fk_school_classes_campus` FOREIGN KEY (`campus_id`) REFERENCES `campuses` (`id`) ON DELETE RESTRICT
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- streams — college side: Pre-Medical, Pre-Engineering, ICS, Commerce, Arts
CREATE TABLE `streams` (
    `id`                 TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `name`               VARCHAR(60) NOT NULL,
    `code`               VARCHAR(12) NOT NULL,
    `applies_from_level` TINYINT UNSIGNED NOT NULL DEFAULT 11,
    `sort_order`         SMALLINT   NOT NULL DEFAULT 0,
    `is_active`          TINYINT(1) NOT NULL DEFAULT 1,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_streams_code` (`code`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `class_streams` (
    `class_id`  SMALLINT UNSIGNED NOT NULL,
    `stream_id` TINYINT UNSIGNED  NOT NULL,
    PRIMARY KEY (`class_id`, `stream_id`),
    KEY `idx_class_streams_stream` (`stream_id`),
    CONSTRAINT `fk_class_streams_class`  FOREIGN KEY (`class_id`)  REFERENCES `school_classes` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_class_streams_stream` FOREIGN KEY (`stream_id`) REFERENCES `streams` (`id`)        ON DELETE CASCADE
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- sections — scoped per session, because 9-A in 2026 is a different cohort than 9-A in 2027.
CREATE TABLE `sections` (
    `id`                  SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `class_id`            SMALLINT UNSIGNED NOT NULL,
    `academic_session_id` SMALLINT UNSIGNED NOT NULL,
    `name`                VARCHAR(20)  NOT NULL COMMENT 'e.g. A',
    `capacity`            SMALLINT UNSIGNED NOT NULL DEFAULT 40,
    `room_no`             VARCHAR(20)  NULL,
    `class_teacher_id`    BIGINT UNSIGNED NULL,
    `sort_order`          SMALLINT     NOT NULL DEFAULT 0,
    `is_active`           TINYINT(1)   NOT NULL DEFAULT 1,
    `created_at`          TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`          TIMESTAMP    NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_sections_class_session_name` (`class_id`, `academic_session_id`, `name`),
    KEY `idx_sections_session_active` (`academic_session_id`, `is_active`),
    KEY `idx_sections_teacher`        (`class_teacher_id`),
    CONSTRAINT `chk_sections_capacity` CHECK (`capacity` > 0),
    CONSTRAINT `fk_sections_class`   FOREIGN KEY (`class_id`)            REFERENCES `school_classes` (`id`)    ON DELETE RESTRICT,
    CONSTRAINT `fk_sections_session` FOREIGN KEY (`academic_session_id`) REFERENCES `academic_sessions` (`id`) ON DELETE RESTRICT
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `subjects` (
    `id`         SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `code`       VARCHAR(20)  NOT NULL,
    `name`       VARCHAR(100) NOT NULL,
    `name_ur`    VARCHAR(100) NULL,
    `type`       ENUM('theory','practical','both') NOT NULL DEFAULT 'theory',
    `is_elective` TINYINT(1)  NOT NULL DEFAULT 0,
    `sort_order` SMALLINT     NOT NULL DEFAULT 0,
    `is_active`  TINYINT(1)   NOT NULL DEFAULT 1,
    `created_at` TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP    NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_subjects_code` (`code`),
    KEY `idx_subjects_active` (`is_active`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- class_subjects — the curriculum: which subject is taught in which class,
-- for which stream, in which session, by whom, and for how many marks.
CREATE TABLE `class_subjects` (
    `id`                  INT UNSIGNED      NOT NULL AUTO_INCREMENT,
    `class_id`            SMALLINT UNSIGNED NOT NULL,
    `stream_id`           TINYINT UNSIGNED  NULL,
    `subject_id`          SMALLINT UNSIGNED NOT NULL,
    `academic_session_id` SMALLINT UNSIGNED NOT NULL,
    `teacher_id`          BIGINT UNSIGNED   NULL,
    `total_marks`         SMALLINT UNSIGNED NOT NULL DEFAULT 100,
    `passing_marks`       SMALLINT UNSIGNED NOT NULL DEFAULT 33,
    `practical_marks`     SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    `is_optional`         TINYINT(1)        NOT NULL DEFAULT 0,
    `sort_order`          SMALLINT          NOT NULL DEFAULT 0,
    `created_at`          TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`          TIMESTAMP         NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_class_subjects_unique` (`academic_session_id`, `class_id`, `stream_id`, `subject_id`),
    KEY `idx_class_subjects_subject` (`subject_id`),
    KEY `idx_class_subjects_teacher` (`teacher_id`, `academic_session_id`),
    CONSTRAINT `chk_class_subjects_marks` CHECK (`passing_marks` <= `total_marks` AND `total_marks` > 0),
    CONSTRAINT `fk_class_subjects_class`   FOREIGN KEY (`class_id`)            REFERENCES `school_classes` (`id`)    ON DELETE CASCADE,
    CONSTRAINT `fk_class_subjects_stream`  FOREIGN KEY (`stream_id`)           REFERENCES `streams` (`id`)           ON DELETE CASCADE,
    CONSTRAINT `fk_class_subjects_subject` FOREIGN KEY (`subject_id`)          REFERENCES `subjects` (`id`)          ON DELETE RESTRICT,
    CONSTRAINT `fk_class_subjects_session` FOREIGN KEY (`academic_session_id`) REFERENCES `academic_sessions` (`id`) ON DELETE RESTRICT
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- grade_scales — grading is DATA, not code, so it can change per session
-- without a deployment.
CREATE TABLE `grade_scales` (
    `id`                  SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `academic_session_id` SMALLINT UNSIGNED NOT NULL,
    `grade`               VARCHAR(5)    NOT NULL,
    `min_percentage`      DECIMAL(5,2)  NOT NULL,
    `max_percentage`      DECIMAL(5,2)  NOT NULL,
    `grade_point`         DECIMAL(3,2)  NOT NULL DEFAULT 0.00,
    `remarks`             VARCHAR(60)   NULL,
    `is_fail`             TINYINT(1)    NOT NULL DEFAULT 0,
    `sort_order`          SMALLINT      NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_grade_scales_session_grade` (`academic_session_id`, `grade`),
    KEY `idx_grade_scales_range` (`academic_session_id`, `min_percentage`, `max_percentage`),
    CONSTRAINT `chk_grade_scales_range` CHECK (`max_percentage` >= `min_percentage`),
    CONSTRAINT `fk_grade_scales_session` FOREIGN KEY (`academic_session_id`) REFERENCES `academic_sessions` (`id`) ON DELETE CASCADE
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `holidays` (
    `id`                  SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `academic_session_id` SMALLINT UNSIGNED NOT NULL,
    `title`               VARCHAR(120) NOT NULL,
    `date_from`           DATE         NOT NULL,
    `date_to`             DATE         NOT NULL,
    `type`                ENUM('public','religious','vacation','emergency','weekend') NOT NULL DEFAULT 'public',
    `applies_to`          ENUM('all','students','staff') NOT NULL DEFAULT 'all',
    `description`         VARCHAR(255) NULL,
    `created_by`          BIGINT UNSIGNED NULL,
    `created_at`          TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`          TIMESTAMP    NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_holidays_session_range` (`academic_session_id`, `date_from`, `date_to`),
    CONSTRAINT `chk_holidays_range` CHECK (`date_to` >= `date_from`),
    CONSTRAINT `fk_holidays_session`    FOREIGN KEY (`academic_session_id`) REFERENCES `academic_sessions` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_holidays_created_by` FOREIGN KEY (`created_by`)          REFERENCES `users` (`id`)             ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `timetables` (
    `id`                  INT UNSIGNED      NOT NULL AUTO_INCREMENT,
    `academic_session_id` SMALLINT UNSIGNED NOT NULL,
    `section_id`          SMALLINT UNSIGNED NOT NULL,
    `subject_id`          SMALLINT UNSIGNED NOT NULL,
    `teacher_id`          BIGINT UNSIGNED   NULL,
    `day_of_week`         TINYINT UNSIGNED  NOT NULL COMMENT '1=Mon … 7=Sun',
    `period_no`           TINYINT UNSIGNED  NOT NULL,
    `start_time`          TIME              NOT NULL,
    `end_time`            TIME              NOT NULL,
    `room_no`             VARCHAR(20)       NULL,
    `created_at`          TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`          TIMESTAMP         NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_timetables_slot` (`academic_session_id`, `section_id`, `day_of_week`, `period_no`),
    KEY `idx_timetables_teacher_slot` (`teacher_id`, `day_of_week`, `period_no`),
    CONSTRAINT `chk_timetables_day`   CHECK (`day_of_week` BETWEEN 1 AND 7),
    CONSTRAINT `chk_timetables_times` CHECK (`end_time` > `start_time`),
    CONSTRAINT `fk_timetables_session` FOREIGN KEY (`academic_session_id`) REFERENCES `academic_sessions` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_timetables_section` FOREIGN KEY (`section_id`)          REFERENCES `sections` (`id`)          ON DELETE CASCADE,
    CONSTRAINT `fk_timetables_subject` FOREIGN KEY (`subject_id`)          REFERENCES `subjects` (`id`)          ON DELETE RESTRICT
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
INSERT INTO `migrations` (`filename`, `batch`) VALUES ('0002_academic_structure.sql', 1);

-- ============================== 0003_students_and_guardians.sql ==============================

-- =============================================================================
-- 0003_students_and_guardians.sql  ·  Domain C — Students, guardians, admissions
-- =============================================================================
USE `iiui_mardan`;
SET FOREIGN_KEY_CHECKS = 0;

-- -----------------------------------------------------------------------------
-- students — the master record. Holds identity facts only; anything that varies
-- by year lives in student_enrollments.
--
-- `current_class_id` / `current_section_id` are a DELIBERATE denormalization:
-- they keep the most-run query in the system ("list students in 9-A") off a
-- three-way join. student_enrollments remains the source of truth, and a
-- trigger (0013) keeps these two columns in sync automatically.
-- -----------------------------------------------------------------------------
CREATE TABLE `students` (
    `id`                 BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `uuid`               CHAR(36)        NOT NULL,
    `user_id`            BIGINT UNSIGNED NULL,
    `registration_no`    VARCHAR(30)     NOT NULL,
    `admission_no`       VARCHAR(30)     NOT NULL,

    `first_name`         VARCHAR(80)     NOT NULL,
    `last_name`          VARCHAR(80)     NULL,
    `name_ur`            VARCHAR(160)    NULL,
    `father_name`        VARCHAR(120)    NOT NULL,
    `father_cnic`        VARCHAR(15)     NULL,
    `father_occupation`  VARCHAR(80)     NULL,
    `father_phone`       VARCHAR(20)     NULL,
    `mother_name`        VARCHAR(120)    NULL,
    `mother_cnic`        VARCHAR(15)     NULL,

    `gender`             ENUM('male','female') NOT NULL,
    `date_of_birth`      DATE            NOT NULL,
    `b_form_no`          VARCHAR(20)     NULL,
    `religion`           VARCHAR(40)     NULL DEFAULT 'Islam',
    `nationality`        VARCHAR(40)     NULL DEFAULT 'Pakistani',
    `blood_group`        ENUM('A+','A-','B+','B-','AB+','AB-','O+','O-') NULL,
    `photo`              VARCHAR(255)    NULL,

    `address`            VARCHAR(255)    NULL,
    `city`               VARCHAR(60)     NULL,
    `district`           VARCHAR(60)     NULL DEFAULT 'Mardan',
    `province`           VARCHAR(60)     NULL DEFAULT 'Khyber Pakhtunkhwa',
    `postal_code`        VARCHAR(10)     NULL,
    `phone`              VARCHAR(20)     NULL,
    `email`              VARCHAR(191)    NULL,

    `admission_date`     DATE            NOT NULL,
    `admission_class_id` SMALLINT UNSIGNED NULL,
    `current_class_id`   SMALLINT UNSIGNED NULL,
    `current_section_id` SMALLINT UNSIGNED NULL,

    `status`             ENUM('active','graduated','left','suspended','expelled','transferred') NOT NULL DEFAULT 'active',
    `previous_school`    VARCHAR(160)    NULL,
    `previous_class`     VARCHAR(40)     NULL,
    `transport_required` TINYINT(1)      NOT NULL DEFAULT 0,
    `is_orphan`          TINYINT(1)      NOT NULL DEFAULT 0,
    `is_disabled`        TINYINT(1)      NOT NULL DEFAULT 0,
    `special_notes`      TEXT            NULL,

    `created_by`         BIGINT UNSIGNED NULL,
    `updated_by`         BIGINT UNSIGNED NULL,
    `created_at`         TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`         TIMESTAMP       NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    `deleted_at`         TIMESTAMP       NULL DEFAULT NULL,

    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_students_uuid`         (`uuid`),
    UNIQUE KEY `uq_students_registration` (`registration_no`),
    UNIQUE KEY `uq_students_admission_no` (`admission_no`),
    UNIQUE KEY `uq_students_user`         (`user_id`),

    -- The single most-executed query in the system: the admin student list.
    KEY `idx_students_listing` (`status`, `current_class_id`, `current_section_id`, `deleted_at`),
    KEY `idx_students_father_cnic` (`father_cnic`),
    KEY `idx_students_admission_date` (`admission_date`),
    KEY `idx_students_transport` (`transport_required`, `status`),
    FULLTEXT KEY `ftx_students_names` (`first_name`, `last_name`, `father_name`),

    CONSTRAINT `chk_students_dob` CHECK (`date_of_birth` < `admission_date`),
    CONSTRAINT `fk_students_user`            FOREIGN KEY (`user_id`)            REFERENCES `users` (`id`)          ON DELETE SET NULL,
    CONSTRAINT `fk_students_admission_class` FOREIGN KEY (`admission_class_id`) REFERENCES `school_classes` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_students_current_class`   FOREIGN KEY (`current_class_id`)   REFERENCES `school_classes` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_students_current_section` FOREIGN KEY (`current_section_id`) REFERENCES `sections` (`id`)       ON DELETE SET NULL,
    CONSTRAINT `fk_students_created_by`      FOREIGN KEY (`created_by`)         REFERENCES `users` (`id`)          ON DELETE SET NULL,
    CONSTRAINT `fk_students_updated_by`      FOREIGN KEY (`updated_by`)         REFERENCES `users` (`id`)          ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- student_enrollments — one row per student per session. The historical spine:
-- this is what makes a 2019 result card reproducible in 2029.
-- -----------------------------------------------------------------------------
CREATE TABLE `student_enrollments` (
    `id`                        BIGINT UNSIGNED   NOT NULL AUTO_INCREMENT,
    `student_id`                BIGINT UNSIGNED   NOT NULL,
    `academic_session_id`       SMALLINT UNSIGNED NOT NULL,
    `class_id`                  SMALLINT UNSIGNED NOT NULL,
    `section_id`                SMALLINT UNSIGNED NOT NULL,
    `stream_id`                 TINYINT UNSIGNED  NULL,
    `roll_no`                   VARCHAR(20)       NOT NULL,
    `enrollment_date`           DATE              NOT NULL,
    `promoted_from_enrollment_id` BIGINT UNSIGNED NULL,
    `result_status`             ENUM('pending','promoted','detained','left') NOT NULL DEFAULT 'pending',
    `status`                    ENUM('active','completed','withdrawn') NOT NULL DEFAULT 'active',
    `remarks`                   VARCHAR(255)      NULL,
    `created_by`                BIGINT UNSIGNED   NULL,
    `created_at`                TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`                TIMESTAMP         NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),

    -- Structurally prevents double-enrolling a student in one academic year.
    UNIQUE KEY `uq_enrollments_student_session` (`student_id`, `academic_session_id`),
    -- Structurally prevents two students sharing a roll number in one section.
    UNIQUE KEY `uq_enrollments_roll` (`academic_session_id`, `section_id`, `roll_no`),

    KEY `idx_enrollments_section_status` (`section_id`, `status`),
    KEY `idx_enrollments_class_session`  (`academic_session_id`, `class_id`, `status`),
    KEY `idx_enrollments_promoted_from`  (`promoted_from_enrollment_id`),

    CONSTRAINT `fk_enrollments_student`   FOREIGN KEY (`student_id`)          REFERENCES `students` (`id`)          ON DELETE RESTRICT,
    CONSTRAINT `fk_enrollments_session`   FOREIGN KEY (`academic_session_id`) REFERENCES `academic_sessions` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_enrollments_class`     FOREIGN KEY (`class_id`)            REFERENCES `school_classes` (`id`)    ON DELETE RESTRICT,
    CONSTRAINT `fk_enrollments_section`   FOREIGN KEY (`section_id`)          REFERENCES `sections` (`id`)          ON DELETE RESTRICT,
    CONSTRAINT `fk_enrollments_stream`    FOREIGN KEY (`stream_id`)           REFERENCES `streams` (`id`)           ON DELETE SET NULL,
    CONSTRAINT `fk_enrollments_prev`      FOREIGN KEY (`promoted_from_enrollment_id`) REFERENCES `student_enrollments` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_enrollments_created_by` FOREIGN KEY (`created_by`)         REFERENCES `users` (`id`)             ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- guardians + student_guardians (M:N) — siblings legitimately share one guardian,
-- and one guardian login must see all their children. A guardian_id column on
-- students would make that impossible.
-- -----------------------------------------------------------------------------
CREATE TABLE `guardians` (
    `id`           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `uuid`         CHAR(36)        NOT NULL,
    `user_id`      BIGINT UNSIGNED NULL,
    `name`         VARCHAR(120)    NOT NULL,
    `relation`     ENUM('father','mother','uncle','aunt','brother','sister','grandfather','other') NOT NULL DEFAULT 'father',
    `cnic`         VARCHAR(15)     NULL,
    `occupation`   VARCHAR(80)     NULL,
    `organization` VARCHAR(120)    NULL,
    `phone`        VARCHAR(20)     NOT NULL,
    `alt_phone`    VARCHAR(20)     NULL,
    `email`        VARCHAR(191)    NULL,
    `address`      VARCHAR(255)    NULL,
    `monthly_income` DECIMAL(12,2) NULL,
    `is_active`    TINYINT(1)      NOT NULL DEFAULT 1,
    `created_at`   TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`   TIMESTAMP       NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    `deleted_at`   TIMESTAMP       NULL DEFAULT NULL,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_guardians_uuid` (`uuid`),
    UNIQUE KEY `uq_guardians_cnic` (`cnic`),
    UNIQUE KEY `uq_guardians_user` (`user_id`),
    KEY `idx_guardians_phone` (`phone`),
    CONSTRAINT `fk_guardians_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `student_guardians` (
    `student_id`          BIGINT UNSIGNED NOT NULL,
    `guardian_id`         BIGINT UNSIGNED NOT NULL,
    `relation`            VARCHAR(40)     NULL,
    `is_primary`          TINYINT(1)      NOT NULL DEFAULT 0,
    `is_emergency_contact` TINYINT(1)     NOT NULL DEFAULT 0,
    `created_at`          TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`student_id`, `guardian_id`),
    KEY `idx_student_guardians_guardian` (`guardian_id`),
    KEY `idx_student_guardians_primary`  (`student_id`, `is_primary`),
    CONSTRAINT `fk_student_guardians_student`  FOREIGN KEY (`student_id`)  REFERENCES `students` (`id`)  ON DELETE CASCADE,
    CONSTRAINT `fk_student_guardians_guardian` FOREIGN KEY (`guardian_id`) REFERENCES `guardians` (`id`) ON DELETE CASCADE
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `student_documents` (
    `id`          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `student_id`  BIGINT UNSIGNED NOT NULL,
    `doc_type`    ENUM('b_form','father_cnic','photo','previous_result','leaving_certificate','domicile','medical','other') NOT NULL,
    `title`       VARCHAR(120)    NOT NULL,
    `file_path`   VARCHAR(255)    NOT NULL,
    `file_name`   VARCHAR(180)    NOT NULL,
    `mime_type`   VARCHAR(100)    NOT NULL,
    `size_bytes`  INT UNSIGNED    NOT NULL,
    `is_verified` TINYINT(1)      NOT NULL DEFAULT 0,
    `verified_by` BIGINT UNSIGNED NULL,
    `verified_at` TIMESTAMP       NULL DEFAULT NULL,
    `uploaded_by` BIGINT UNSIGNED NULL,
    `created_at`  TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_student_documents_student` (`student_id`, `doc_type`),
    CONSTRAINT `fk_student_documents_student`     FOREIGN KEY (`student_id`)  REFERENCES `students` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_student_documents_verified_by` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`)    ON DELETE SET NULL,
    CONSTRAINT `fk_student_documents_uploaded_by` FOREIGN KEY (`uploaded_by`) REFERENCES `users` (`id`)    ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- student_promotions — the audit trail of bulk promotion runs.
CREATE TABLE `student_promotions` (
    `id`              BIGINT UNSIGNED   NOT NULL AUTO_INCREMENT,
    `student_id`      BIGINT UNSIGNED   NOT NULL,
    `from_session_id` SMALLINT UNSIGNED NOT NULL,
    `to_session_id`   SMALLINT UNSIGNED NOT NULL,
    `from_class_id`   SMALLINT UNSIGNED NOT NULL,
    `to_class_id`     SMALLINT UNSIGNED NULL,
    `decision`        ENUM('promoted','detained','graduated','left') NOT NULL,
    `batch_ref`       CHAR(36)          NULL COMMENT 'groups one bulk run',
    `remarks`         VARCHAR(255)      NULL,
    `processed_by`    BIGINT UNSIGNED   NULL,
    `processed_at`    TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_promotions_student_from` (`student_id`, `from_session_id`),
    KEY `idx_promotions_batch` (`batch_ref`),
    CONSTRAINT `fk_promotions_student`      FOREIGN KEY (`student_id`)      REFERENCES `students` (`id`)          ON DELETE CASCADE,
    CONSTRAINT `fk_promotions_from_session` FOREIGN KEY (`from_session_id`) REFERENCES `academic_sessions` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_promotions_to_session`   FOREIGN KEY (`to_session_id`)   REFERENCES `academic_sessions` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_promotions_from_class`   FOREIGN KEY (`from_class_id`)   REFERENCES `school_classes` (`id`)    ON DELETE RESTRICT,
    CONSTRAINT `fk_promotions_to_class`     FOREIGN KEY (`to_class_id`)     REFERENCES `school_classes` (`id`)    ON DELETE RESTRICT,
    CONSTRAINT `fk_promotions_processed_by` FOREIGN KEY (`processed_by`)    REFERENCES `users` (`id`)             ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `student_transfers` (
    `id`               BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `student_id`       BIGINT UNSIGNED NOT NULL,
    `type`             ENUM('leaving','transfer','character') NOT NULL DEFAULT 'leaving',
    `certificate_no`   VARCHAR(30)     NOT NULL,
    `issue_date`       DATE            NOT NULL,
    `last_class_id`    SMALLINT UNSIGNED NULL,
    `reason`           VARCHAR(255)    NULL,
    `conduct`          ENUM('excellent','good','satisfactory','poor') NOT NULL DEFAULT 'good',
    `dues_cleared`     TINYINT(1)      NOT NULL DEFAULT 0,
    `file_path`        VARCHAR(255)    NULL,
    `issued_by`        BIGINT UNSIGNED NULL,
    `created_at`       TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_transfers_certificate` (`certificate_no`),
    KEY `idx_transfers_student` (`student_id`),
    CONSTRAINT `fk_transfers_student`    FOREIGN KEY (`student_id`)    REFERENCES `students` (`id`)       ON DELETE RESTRICT,
    CONSTRAINT `fk_transfers_last_class` FOREIGN KEY (`last_class_id`) REFERENCES `school_classes` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_transfers_issued_by`  FOREIGN KEY (`issued_by`)     REFERENCES `users` (`id`)          ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- admission_applications — public-facing, pre-enrollment. Kept separate from
-- `students` so an unsuccessful applicant never becomes a student record.
-- -----------------------------------------------------------------------------
CREATE TABLE `admission_applications` (
    `id`                   BIGINT UNSIGNED   NOT NULL AUTO_INCREMENT,
    `application_no`       VARCHAR(30)       NOT NULL,
    `academic_session_id`  SMALLINT UNSIGNED NOT NULL,
    `class_id`             SMALLINT UNSIGNED NOT NULL,
    `stream_id`            TINYINT UNSIGNED  NULL,

    `applicant_name`       VARCHAR(120)      NOT NULL,
    `father_name`          VARCHAR(120)      NOT NULL,
    `father_cnic`          VARCHAR(15)       NULL,
    `date_of_birth`        DATE              NOT NULL,
    `gender`               ENUM('male','female') NOT NULL,
    `b_form_no`            VARCHAR(20)       NULL,
    `phone`                VARCHAR(20)       NOT NULL,
    `email`                VARCHAR(191)      NULL,
    `address`              VARCHAR(255)      NULL,
    `previous_school`      VARCHAR(160)      NULL,
    `previous_percentage`  DECIMAL(5,2)      NULL,
    `photo`                VARCHAR(255)      NULL,
    `documents`            JSON              NULL,

    `status`               ENUM('submitted','under_review','shortlisted','test_scheduled','test_taken','interview','admitted','rejected','waitlisted','withdrawn') NOT NULL DEFAULT 'submitted',
    `test_date`            DATETIME          NULL,
    `test_roll_no`         VARCHAR(20)       NULL,
    `test_score`           DECIMAL(6,2)      NULL,
    `interview_remarks`    VARCHAR(255)      NULL,
    `merit_position`       SMALLINT UNSIGNED NULL,

    `converted_student_id` BIGINT UNSIGNED   NULL,
    `reviewed_by`          BIGINT UNSIGNED   NULL,
    `reviewed_at`          TIMESTAMP         NULL DEFAULT NULL,
    `remarks`              VARCHAR(255)      NULL,
    `submitted_ip`         VARBINARY(16)     NULL,
    `created_at`           TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`           TIMESTAMP         NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,

    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_applications_no`      (`application_no`),
    UNIQUE KEY `uq_applications_student` (`converted_student_id`),
    KEY `idx_applications_pipeline` (`academic_session_id`, `status`, `class_id`),
    KEY `idx_applications_merit`    (`academic_session_id`, `class_id`, `test_score`),
    KEY `idx_applications_phone`    (`phone`),

    CONSTRAINT `fk_applications_session` FOREIGN KEY (`academic_session_id`)  REFERENCES `academic_sessions` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_applications_class`   FOREIGN KEY (`class_id`)             REFERENCES `school_classes` (`id`)    ON DELETE RESTRICT,
    CONSTRAINT `fk_applications_stream`  FOREIGN KEY (`stream_id`)            REFERENCES `streams` (`id`)           ON DELETE SET NULL,
    CONSTRAINT `fk_applications_student` FOREIGN KEY (`converted_student_id`) REFERENCES `students` (`id`)          ON DELETE SET NULL,
    CONSTRAINT `fk_applications_reviewer` FOREIGN KEY (`reviewed_by`)         REFERENCES `users` (`id`)             ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
INSERT INTO `migrations` (`filename`, `batch`) VALUES ('0003_students_and_guardians.sql', 1);

-- ============================== 0004_staff_and_hr.sql ==============================

-- =============================================================================
-- 0004_staff_and_hr.sql  ·  Domain D — Staff, departments, payroll
-- -----------------------------------------------------------------------------
-- Also resolves the deferred foreign keys from 0002: departments.head_staff_id
-- and staff.department_id form a cycle, so the FK is added after both exist.
-- =============================================================================
USE `iiui_mardan`;
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE `departments` (
    `id`            SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `name`          VARCHAR(100)    NOT NULL,
    `code`          VARCHAR(15)     NOT NULL,
    `head_staff_id` BIGINT UNSIGNED NULL,
    `description`   VARCHAR(255)    NULL,
    `sort_order`    SMALLINT        NOT NULL DEFAULT 0,
    `is_active`     TINYINT(1)      NOT NULL DEFAULT 1,
    `created_at`    TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`    TIMESTAMP       NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_departments_code` (`code`),
    KEY `idx_departments_head` (`head_staff_id`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `designations` (
    `id`         SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `name`       VARCHAR(100) NOT NULL,
    `category`   ENUM('teaching','non_teaching','management','support') NOT NULL DEFAULT 'teaching',
    `rank`       TINYINT UNSIGNED NOT NULL DEFAULT 50,
    `is_active`  TINYINT(1)   NOT NULL DEFAULT 1,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_designations_name` (`name`),
    KEY `idx_designations_category` (`category`, `rank`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- staff — `is_public_profile` + `bio` let the website's Faculty page read
-- straight from this table. One source of truth; no parallel "faculty" table
-- to drift out of sync.
-- Sensitive columns (cnic, account_no) are VARBINARY: the application stores
-- them AES-256-GCM encrypted, so a stolen dump alone does not expose them.
-- -----------------------------------------------------------------------------
CREATE TABLE `staff` (
    `id`                BIGINT UNSIGNED   NOT NULL AUTO_INCREMENT,
    `uuid`              CHAR(36)          NOT NULL,
    `user_id`           BIGINT UNSIGNED   NULL,
    `employee_no`       VARCHAR(30)       NOT NULL,

    `first_name`        VARCHAR(80)       NOT NULL,
    `last_name`         VARCHAR(80)       NULL,
    `father_name`       VARCHAR(120)      NULL,
    `cnic`              VARBINARY(255)    NULL,
    `cnic_hash`         CHAR(64)          NULL COMMENT 'SHA-256 for uniqueness/lookup without decryption',
    `gender`            ENUM('male','female') NOT NULL,
    `date_of_birth`     DATE              NULL,
    `marital_status`    ENUM('single','married','widowed','divorced') NULL,
    `blood_group`       ENUM('A+','A-','B+','B-','AB+','AB-','O+','O-') NULL,
    `photo`             VARCHAR(255)      NULL,

    `department_id`     SMALLINT UNSIGNED NULL,
    `designation_id`    SMALLINT UNSIGNED NULL,
    `qualification`     VARCHAR(160)      NULL,
    `specialization`    VARCHAR(160)      NULL,
    `experience_years`  TINYINT UNSIGNED  NOT NULL DEFAULT 0,

    `joining_date`      DATE              NOT NULL,
    `employment_type`   ENUM('permanent','contract','visiting','probation') NOT NULL DEFAULT 'probation',
    `contract_end_date` DATE              NULL,
    `basic_salary`      DECIMAL(12,2)     NOT NULL DEFAULT 0.00,
    `bank_name`         VARCHAR(80)       NULL,
    `account_no`        VARBINARY(255)    NULL,

    `phone`             VARCHAR(20)       NULL,
    `emergency_contact` VARCHAR(20)       NULL,
    `email`             VARCHAR(191)      NULL,
    `address`           VARCHAR(255)      NULL,

    `is_teaching`       TINYINT(1)        NOT NULL DEFAULT 1,
    `is_public_profile` TINYINT(1)        NOT NULL DEFAULT 0,
    `slug`              VARCHAR(140)      NULL,
    `bio`               TEXT              NULL,
    `sort_order`        SMALLINT          NOT NULL DEFAULT 0,

    `status`            ENUM('active','on_leave','resigned','terminated','retired') NOT NULL DEFAULT 'active',
    `left_date`         DATE              NULL,
    `created_by`        BIGINT UNSIGNED   NULL,
    `updated_by`        BIGINT UNSIGNED   NULL,
    `created_at`        TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`        TIMESTAMP         NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    `deleted_at`        TIMESTAMP         NULL DEFAULT NULL,

    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_staff_uuid`        (`uuid`),
    UNIQUE KEY `uq_staff_employee_no` (`employee_no`),
    UNIQUE KEY `uq_staff_user`        (`user_id`),
    UNIQUE KEY `uq_staff_cnic_hash`   (`cnic_hash`),
    UNIQUE KEY `uq_staff_slug`        (`slug`),
    KEY `idx_staff_listing`  (`status`, `department_id`, `deleted_at`),
    KEY `idx_staff_teaching` (`is_teaching`, `status`),
    KEY `idx_staff_public`   (`is_public_profile`, `sort_order`),
    KEY `idx_staff_contract` (`contract_end_date`, `status`),
    KEY `idx_staff_designation` (`designation_id`),
    FULLTEXT KEY `ftx_staff_names` (`first_name`, `last_name`),

    CONSTRAINT `fk_staff_user`        FOREIGN KEY (`user_id`)        REFERENCES `users` (`id`)        ON DELETE SET NULL,
    CONSTRAINT `fk_staff_department`  FOREIGN KEY (`department_id`)  REFERENCES `departments` (`id`)  ON DELETE SET NULL,
    CONSTRAINT `fk_staff_designation` FOREIGN KEY (`designation_id`) REFERENCES `designations` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_staff_created_by`  FOREIGN KEY (`created_by`)     REFERENCES `users` (`id`)        ON DELETE SET NULL,
    CONSTRAINT `fk_staff_updated_by`  FOREIGN KEY (`updated_by`)     REFERENCES `users` (`id`)        ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `staff_subjects` (
    `id`                  INT UNSIGNED      NOT NULL AUTO_INCREMENT,
    `staff_id`            BIGINT UNSIGNED   NOT NULL,
    `subject_id`          SMALLINT UNSIGNED NOT NULL,
    `class_id`            SMALLINT UNSIGNED NOT NULL,
    `section_id`          SMALLINT UNSIGNED NULL,
    `academic_session_id` SMALLINT UNSIGNED NOT NULL,
    `is_primary`          TINYINT(1)        NOT NULL DEFAULT 1,
    `created_at`          TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_staff_subjects_assignment` (`academic_session_id`, `staff_id`, `subject_id`, `class_id`, `section_id`),
    -- Drives the teacher data-scope: "which students may this teacher touch?"
    KEY `idx_staff_subjects_scope` (`staff_id`, `academic_session_id`, `section_id`),
    KEY `idx_staff_subjects_section` (`section_id`, `subject_id`),
    CONSTRAINT `fk_staff_subjects_staff`   FOREIGN KEY (`staff_id`)            REFERENCES `staff` (`id`)             ON DELETE CASCADE,
    CONSTRAINT `fk_staff_subjects_subject` FOREIGN KEY (`subject_id`)          REFERENCES `subjects` (`id`)          ON DELETE CASCADE,
    CONSTRAINT `fk_staff_subjects_class`   FOREIGN KEY (`class_id`)            REFERENCES `school_classes` (`id`)    ON DELETE CASCADE,
    CONSTRAINT `fk_staff_subjects_section` FOREIGN KEY (`section_id`)          REFERENCES `sections` (`id`)          ON DELETE CASCADE,
    CONSTRAINT `fk_staff_subjects_session` FOREIGN KEY (`academic_session_id`) REFERENCES `academic_sessions` (`id`) ON DELETE CASCADE
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `staff_documents` (
    `id`          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `staff_id`    BIGINT UNSIGNED NOT NULL,
    `doc_type`    ENUM('cnic','degree','transcript','experience','appointment','contract','photo','other') NOT NULL,
    `title`       VARCHAR(120)    NOT NULL,
    `file_path`   VARCHAR(255)    NOT NULL,
    `file_name`   VARCHAR(180)    NOT NULL,
    `mime_type`   VARCHAR(100)    NOT NULL,
    `size_bytes`  INT UNSIGNED    NOT NULL,
    `is_verified` TINYINT(1)      NOT NULL DEFAULT 0,
    `uploaded_by` BIGINT UNSIGNED NULL,
    `created_at`  TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_staff_documents_staff` (`staff_id`, `doc_type`),
    CONSTRAINT `fk_staff_documents_staff`       FOREIGN KEY (`staff_id`)    REFERENCES `staff` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_staff_documents_uploaded_by` FOREIGN KEY (`uploaded_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- payrolls — allowances/deductions are JSON because their shape varies per
-- employee and per policy year. A fixed column per allowance type would mean
-- a migration every time HR invents a new stipend.
CREATE TABLE `payrolls` (
    `id`             BIGINT UNSIGNED  NOT NULL AUTO_INCREMENT,
    `staff_id`       BIGINT UNSIGNED  NOT NULL,
    `month`          TINYINT UNSIGNED NOT NULL,
    `year`           SMALLINT UNSIGNED NOT NULL,
    `basic_salary`   DECIMAL(12,2)    NOT NULL DEFAULT 0.00,
    `allowances`     JSON             NULL,
    `deductions`     JSON             NULL,
    `gross_salary`   DECIMAL(12,2)    NOT NULL DEFAULT 0.00,
    `total_deduction` DECIMAL(12,2)   NOT NULL DEFAULT 0.00,
    `net_salary`     DECIMAL(12,2)    NOT NULL DEFAULT 0.00,
    `working_days`   TINYINT UNSIGNED NOT NULL DEFAULT 0,
    `present_days`   DECIMAL(4,1)     NOT NULL DEFAULT 0.0,
    `leave_days`     DECIMAL(4,1)     NOT NULL DEFAULT 0.0,
    `absent_days`    DECIMAL(4,1)     NOT NULL DEFAULT 0.0,
    `status`         ENUM('draft','approved','paid','cancelled') NOT NULL DEFAULT 'draft',
    `payment_method` ENUM('cash','bank_transfer','cheque') NULL,
    `paid_at`        TIMESTAMP        NULL DEFAULT NULL,
    `generated_by`   BIGINT UNSIGNED  NULL,
    `approved_by`    BIGINT UNSIGNED  NULL,
    `remarks`        VARCHAR(255)     NULL,
    `created_at`     TIMESTAMP        NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`     TIMESTAMP        NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_payrolls_staff_period` (`staff_id`, `year`, `month`),
    KEY `idx_payrolls_period_status` (`year`, `month`, `status`),
    CONSTRAINT `chk_payrolls_month` CHECK (`month` BETWEEN 1 AND 12),
    CONSTRAINT `fk_payrolls_staff`        FOREIGN KEY (`staff_id`)     REFERENCES `staff` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_payrolls_generated_by` FOREIGN KEY (`generated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_payrolls_approved_by`  FOREIGN KEY (`approved_by`)  REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- Deferred foreign keys — these point at `staff`, which did not exist when
-- 0002 ran, and one of them (departments.head_staff_id) is part of a cycle.
-- -----------------------------------------------------------------------------
ALTER TABLE `departments`
    ADD CONSTRAINT `fk_departments_head` FOREIGN KEY (`head_staff_id`) REFERENCES `staff` (`id`) ON DELETE SET NULL;

ALTER TABLE `sections`
    ADD CONSTRAINT `fk_sections_class_teacher` FOREIGN KEY (`class_teacher_id`) REFERENCES `staff` (`id`) ON DELETE SET NULL;

ALTER TABLE `class_subjects`
    ADD CONSTRAINT `fk_class_subjects_teacher` FOREIGN KEY (`teacher_id`) REFERENCES `staff` (`id`) ON DELETE SET NULL;

ALTER TABLE `timetables`
    ADD CONSTRAINT `fk_timetables_teacher` FOREIGN KEY (`teacher_id`) REFERENCES `staff` (`id`) ON DELETE SET NULL;

SET FOREIGN_KEY_CHECKS = 1;
INSERT INTO `migrations` (`filename`, `batch`) VALUES ('0004_staff_and_hr.sql', 1);

-- ============================== 0005_attendance.sql ==============================

-- =============================================================================
-- 0005_attendance.sql  ·  Domain E — Student & staff attendance, leave
-- =============================================================================
USE `iiui_mardan`;
SET FOREIGN_KEY_CHECKS = 0;

-- -----------------------------------------------------------------------------
-- student_attendance — the highest-volume table in the system
-- (~250k rows/year at 1,200 students).
--
-- UNIQUE(student_id, attendance_date) is the most important constraint in this
-- domain: it makes double-marking structurally impossible no matter what the
-- UI, a retried AJAX call, or a bulk import does.
--
-- class_id / section_id are denormalized from the enrollment so the daily
-- marking sheet and the monthly register never need a join to filter.
-- -----------------------------------------------------------------------------
CREATE TABLE `student_attendance` (
    `id`                  BIGINT UNSIGNED   NOT NULL AUTO_INCREMENT,
    `student_id`          BIGINT UNSIGNED   NOT NULL,
    `enrollment_id`       BIGINT UNSIGNED   NOT NULL,
    `academic_session_id` SMALLINT UNSIGNED NOT NULL,
    `class_id`            SMALLINT UNSIGNED NOT NULL,
    `section_id`          SMALLINT UNSIGNED NOT NULL,
    `attendance_date`     DATE              NOT NULL,
    `status`              ENUM('present','absent','late','leave','half_day') NOT NULL,
    `check_in`            TIME              NULL,
    `remarks`             VARCHAR(160)      NULL,
    `marked_by`           BIGINT UNSIGNED   NULL,
    `marked_at`           TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`          TIMESTAMP         NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,

    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_attendance_student_date` (`student_id`, `attendance_date`),

    -- Daily marking sheet: "give me 9-A for 14 August"
    KEY `idx_attendance_sheet` (`section_id`, `attendance_date`),
    -- Monthly percentage reports and shortage lists
    KEY `idx_attendance_report` (`academic_session_id`, `student_id`, `status`),
    -- Class-wide daily summary for the dashboard
    KEY `idx_attendance_class_date` (`academic_session_id`, `class_id`, `attendance_date`, `status`),
    KEY `idx_attendance_enrollment` (`enrollment_id`),

    CONSTRAINT `fk_attendance_student`    FOREIGN KEY (`student_id`)          REFERENCES `students` (`id`)            ON DELETE RESTRICT,
    CONSTRAINT `fk_attendance_enrollment` FOREIGN KEY (`enrollment_id`)       REFERENCES `student_enrollments` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_attendance_session`    FOREIGN KEY (`academic_session_id`) REFERENCES `academic_sessions` (`id`)   ON DELETE RESTRICT,
    CONSTRAINT `fk_attendance_class`      FOREIGN KEY (`class_id`)            REFERENCES `school_classes` (`id`)      ON DELETE RESTRICT,
    CONSTRAINT `fk_attendance_section`    FOREIGN KEY (`section_id`)          REFERENCES `sections` (`id`)            ON DELETE RESTRICT,
    CONSTRAINT `fk_attendance_marked_by`  FOREIGN KEY (`marked_by`)           REFERENCES `users` (`id`)               ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `staff_attendance` (
    `id`                  BIGINT UNSIGNED   NOT NULL AUTO_INCREMENT,
    `staff_id`            BIGINT UNSIGNED   NOT NULL,
    `academic_session_id` SMALLINT UNSIGNED NOT NULL,
    `attendance_date`     DATE              NOT NULL,
    `status`              ENUM('present','absent','late','leave','half_day','official_duty') NOT NULL,
    `check_in`            TIME              NULL,
    `check_out`           TIME              NULL,
    `remarks`             VARCHAR(160)      NULL,
    `marked_by`           BIGINT UNSIGNED   NULL,
    `marked_at`           TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`          TIMESTAMP         NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_staff_attendance_date` (`staff_id`, `attendance_date`),
    KEY `idx_staff_attendance_date`   (`attendance_date`, `status`),
    KEY `idx_staff_attendance_report` (`academic_session_id`, `staff_id`, `status`),
    CONSTRAINT `chk_staff_attendance_times` CHECK (`check_out` IS NULL OR `check_in` IS NULL OR `check_out` >= `check_in`),
    CONSTRAINT `fk_staff_attendance_staff`     FOREIGN KEY (`staff_id`)            REFERENCES `staff` (`id`)             ON DELETE RESTRICT,
    CONSTRAINT `fk_staff_attendance_session`   FOREIGN KEY (`academic_session_id`) REFERENCES `academic_sessions` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_staff_attendance_marked_by` FOREIGN KEY (`marked_by`)           REFERENCES `users` (`id`)             ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- leave_applications — polymorphic applicant (student or staff). The pair
-- (applicant_type, applicant_id) cannot carry a foreign key, so referential
-- integrity here is enforced by the service layer; the trade-off buys one
-- approval workflow instead of two near-identical tables.
CREATE TABLE `leave_applications` (
    `id`                  BIGINT UNSIGNED   NOT NULL AUTO_INCREMENT,
    `applicant_type`      ENUM('student','staff') NOT NULL,
    `applicant_id`        BIGINT UNSIGNED   NOT NULL,
    `academic_session_id` SMALLINT UNSIGNED NOT NULL,
    `leave_type`          ENUM('sick','casual','emergency','maternity','study','unpaid','other') NOT NULL DEFAULT 'casual',
    `from_date`           DATE              NOT NULL,
    `to_date`             DATE              NOT NULL,
    `total_days`          DECIMAL(4,1)      NOT NULL DEFAULT 1.0,
    `reason`              VARCHAR(500)      NOT NULL,
    `attachment`          VARCHAR(255)      NULL,
    `status`              ENUM('pending','approved','rejected','cancelled') NOT NULL DEFAULT 'pending',
    `reviewed_by`         BIGINT UNSIGNED   NULL,
    `reviewed_at`         TIMESTAMP         NULL DEFAULT NULL,
    `review_remarks`      VARCHAR(255)      NULL,
    `applied_by`          BIGINT UNSIGNED   NULL,
    `created_at`          TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`          TIMESTAMP         NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_leaves_applicant` (`applicant_type`, `applicant_id`, `status`),
    KEY `idx_leaves_pending`   (`status`, `from_date`),
    KEY `idx_leaves_session`   (`academic_session_id`, `from_date`, `to_date`),
    CONSTRAINT `chk_leaves_range` CHECK (`to_date` >= `from_date`),
    CONSTRAINT `fk_leaves_session`     FOREIGN KEY (`academic_session_id`) REFERENCES `academic_sessions` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_leaves_reviewed_by` FOREIGN KEY (`reviewed_by`)         REFERENCES `users` (`id`)             ON DELETE SET NULL,
    CONSTRAINT `fk_leaves_applied_by`  FOREIGN KEY (`applied_by`)          REFERENCES `users` (`id`)             ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- attendance_monthly_summary — pre-aggregated, rebuilt nightly by cron.
-- Exists so that a five-year attendance report never scans 1.25M raw rows.
-- The raw table remains the source of truth; this is a derived cache.
CREATE TABLE `attendance_monthly_summary` (
    `id`                  BIGINT UNSIGNED   NOT NULL AUTO_INCREMENT,
    `student_id`          BIGINT UNSIGNED   NOT NULL,
    `academic_session_id` SMALLINT UNSIGNED NOT NULL,
    `class_id`            SMALLINT UNSIGNED NOT NULL,
    `section_id`          SMALLINT UNSIGNED NOT NULL,
    `year`                SMALLINT UNSIGNED NOT NULL,
    `month`               TINYINT UNSIGNED  NOT NULL,
    `working_days`        TINYINT UNSIGNED  NOT NULL DEFAULT 0,
    `present_days`        TINYINT UNSIGNED  NOT NULL DEFAULT 0,
    `absent_days`         TINYINT UNSIGNED  NOT NULL DEFAULT 0,
    `late_days`           TINYINT UNSIGNED  NOT NULL DEFAULT 0,
    `leave_days`          TINYINT UNSIGNED  NOT NULL DEFAULT 0,
    `half_days`           TINYINT UNSIGNED  NOT NULL DEFAULT 0,
    `percentage`          DECIMAL(5,2)      NOT NULL DEFAULT 0.00,
    `computed_at`         TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_att_summary_student_period` (`student_id`, `year`, `month`),
    KEY `idx_att_summary_section` (`section_id`, `year`, `month`),
    KEY `idx_att_summary_shortage` (`academic_session_id`, `percentage`),
    CONSTRAINT `chk_att_summary_month` CHECK (`month` BETWEEN 1 AND 12),
    CONSTRAINT `fk_att_summary_student` FOREIGN KEY (`student_id`)          REFERENCES `students` (`id`)          ON DELETE CASCADE,
    CONSTRAINT `fk_att_summary_session` FOREIGN KEY (`academic_session_id`) REFERENCES `academic_sessions` (`id`) ON DELETE CASCADE
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
INSERT INTO `migrations` (`filename`, `batch`) VALUES ('0005_attendance.sql', 1);

-- ============================== 0006_examination.sql ==============================

-- =============================================================================
-- 0006_examination.sql  ·  Domain F — Exam terms, marks, grading, results
-- =============================================================================
USE `iiui_mardan`;
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE `exam_terms` (
    `id`                  SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `academic_session_id` SMALLINT UNSIGNED NOT NULL,
    `name`                VARCHAR(80)  NOT NULL COMMENT 'e.g. First Term',
    `type`                ENUM('monthly','mid','final','test','pre_board') NOT NULL DEFAULT 'mid',
    `start_date`          DATE         NOT NULL,
    `end_date`            DATE         NOT NULL,
    `weightage`           DECIMAL(5,2) NOT NULL DEFAULT 100.00 COMMENT 'contribution to the final result',
    `is_result_published` TINYINT(1)   NOT NULL DEFAULT 0,
    `published_at`        TIMESTAMP    NULL DEFAULT NULL,
    `published_by`        BIGINT UNSIGNED NULL,
    `status`              ENUM('planned','ongoing','marking','completed','cancelled') NOT NULL DEFAULT 'planned',
    `sort_order`          SMALLINT     NOT NULL DEFAULT 0,
    `created_at`          TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`          TIMESTAMP    NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_exam_terms_session_name` (`academic_session_id`, `name`),
    KEY `idx_exam_terms_session_status` (`academic_session_id`, `status`),
    CONSTRAINT `chk_exam_terms_dates`     CHECK (`end_date` >= `start_date`),
    CONSTRAINT `chk_exam_terms_weightage` CHECK (`weightage` > 0 AND `weightage` <= 100),
    CONSTRAINT `fk_exam_terms_session`      FOREIGN KEY (`academic_session_id`) REFERENCES `academic_sessions` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_exam_terms_published_by` FOREIGN KEY (`published_by`)        REFERENCES `users` (`id`)             ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `exams` (
    `id`               INT UNSIGNED      NOT NULL AUTO_INCREMENT,
    `exam_term_id`     SMALLINT UNSIGNED NOT NULL,
    `class_id`         SMALLINT UNSIGNED NOT NULL,
    `stream_id`        TINYINT UNSIGNED  NULL,
    `subject_id`       SMALLINT UNSIGNED NOT NULL,
    `exam_date`        DATE              NOT NULL,
    `start_time`       TIME              NULL,
    `end_time`         TIME              NULL,
    `total_marks`      SMALLINT UNSIGNED NOT NULL DEFAULT 100,
    `passing_marks`    SMALLINT UNSIGNED NOT NULL DEFAULT 33,
    `practical_total`  SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    `practical_passing` SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    `room_no`          VARCHAR(20)       NULL,
    `invigilator_id`   BIGINT UNSIGNED   NULL,
    `is_marks_locked`  TINYINT(1)        NOT NULL DEFAULT 0,
    `created_by`       BIGINT UNSIGNED   NULL,
    `created_at`       TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`       TIMESTAMP         NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_exams_term_class_subject` (`exam_term_id`, `class_id`, `stream_id`, `subject_id`),
    KEY `idx_exams_date`    (`exam_date`),
    KEY `idx_exams_class`   (`class_id`, `exam_term_id`),
    KEY `idx_exams_subject` (`subject_id`),
    CONSTRAINT `chk_exams_marks` CHECK (`passing_marks` <= `total_marks` AND `total_marks` > 0),
    CONSTRAINT `chk_exams_times` CHECK (`end_time` IS NULL OR `start_time` IS NULL OR `end_time` > `start_time`),
    CONSTRAINT `fk_exams_term`        FOREIGN KEY (`exam_term_id`)  REFERENCES `exam_terms` (`id`)     ON DELETE CASCADE,
    CONSTRAINT `fk_exams_class`       FOREIGN KEY (`class_id`)      REFERENCES `school_classes` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_exams_stream`      FOREIGN KEY (`stream_id`)     REFERENCES `streams` (`id`)        ON DELETE SET NULL,
    CONSTRAINT `fk_exams_subject`     FOREIGN KEY (`subject_id`)    REFERENCES `subjects` (`id`)       ON DELETE RESTRICT,
    CONSTRAINT `fk_exams_invigilator` FOREIGN KEY (`invigilator_id`) REFERENCES `staff` (`id`)         ON DELETE SET NULL,
    CONSTRAINT `fk_exams_created_by`  FOREIGN KEY (`created_by`)    REFERENCES `users` (`id`)          ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- marks — four-eyes control lives in these columns:
--   entered_by  → the subject teacher records the mark
--   verified_by → the exam controller confirms it
--   is_locked   → the row freezes; further edits need a permission AND write
--                 an audit_logs entry (trigger in 0013).
-- -----------------------------------------------------------------------------
CREATE TABLE `marks` (
    `id`                 BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `exam_id`            INT UNSIGNED    NOT NULL,
    `student_id`         BIGINT UNSIGNED NOT NULL,
    `enrollment_id`      BIGINT UNSIGNED NOT NULL,
    `obtained_marks`     DECIMAL(6,2)    NULL,
    `practical_obtained` DECIMAL(6,2)    NULL,
    `total_obtained`     DECIMAL(6,2)    GENERATED ALWAYS AS (COALESCE(`obtained_marks`,0) + COALESCE(`practical_obtained`,0)) STORED,
    `is_absent`          TINYINT(1)      NOT NULL DEFAULT 0,
    `grade`              VARCHAR(5)      NULL,
    `grade_point`        DECIMAL(3,2)    NULL,
    `remarks`            VARCHAR(160)    NULL,
    `entered_by`         BIGINT UNSIGNED NULL,
    `entered_at`         TIMESTAMP       NULL DEFAULT NULL,
    `verified_by`        BIGINT UNSIGNED NULL,
    `verified_at`        TIMESTAMP       NULL DEFAULT NULL,
    `is_locked`          TINYINT(1)      NOT NULL DEFAULT 0,
    `created_at`         TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`         TIMESTAMP       NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_marks_exam_student` (`exam_id`, `student_id`),
    KEY `idx_marks_student`    (`student_id`),
    KEY `idx_marks_enrollment` (`enrollment_id`),
    KEY `idx_marks_unverified` (`exam_id`, `verified_at`),
    CONSTRAINT `chk_marks_non_negative` CHECK (
        (`obtained_marks`     IS NULL OR `obtained_marks`     >= 0) AND
        (`practical_obtained` IS NULL OR `practical_obtained` >= 0)
    ),
    CONSTRAINT `fk_marks_exam`        FOREIGN KEY (`exam_id`)       REFERENCES `exams` (`id`)               ON DELETE CASCADE,
    CONSTRAINT `fk_marks_student`     FOREIGN KEY (`student_id`)    REFERENCES `students` (`id`)            ON DELETE RESTRICT,
    CONSTRAINT `fk_marks_enrollment`  FOREIGN KEY (`enrollment_id`) REFERENCES `student_enrollments` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_marks_entered_by`  FOREIGN KEY (`entered_by`)    REFERENCES `users` (`id`)               ON DELETE SET NULL,
    CONSTRAINT `fk_marks_verified_by` FOREIGN KEY (`verified_by`)   REFERENCES `users` (`id`)               ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- result_summaries — computed per student per term by sp_compile_results.
-- Positions are stored, not calculated on read: a result card must show the
-- same rank in 2029 as it did the day it was published, even if a mark is
-- later corrected for a different student.
CREATE TABLE `result_summaries` (
    `id`                  BIGINT UNSIGNED   NOT NULL AUTO_INCREMENT,
    `student_id`          BIGINT UNSIGNED   NOT NULL,
    `enrollment_id`       BIGINT UNSIGNED   NOT NULL,
    `exam_term_id`        SMALLINT UNSIGNED NOT NULL,
    `academic_session_id` SMALLINT UNSIGNED NOT NULL,
    `class_id`            SMALLINT UNSIGNED NOT NULL,
    `section_id`          SMALLINT UNSIGNED NOT NULL,
    `total_marks`         DECIMAL(8,2)      NOT NULL DEFAULT 0.00,
    `obtained_marks`      DECIMAL(8,2)      NOT NULL DEFAULT 0.00,
    `percentage`          DECIMAL(5,2)      NOT NULL DEFAULT 0.00,
    `grade`               VARCHAR(5)        NULL,
    `grade_point`         DECIMAL(3,2)      NULL,
    `position_in_section` SMALLINT UNSIGNED NULL,
    `position_in_class`   SMALLINT UNSIGNED NULL,
    `subjects_total`      TINYINT UNSIGNED  NOT NULL DEFAULT 0,
    `subjects_failed`     TINYINT UNSIGNED  NOT NULL DEFAULT 0,
    `result_status`       ENUM('pass','fail','absent','pending','withheld') NOT NULL DEFAULT 'pending',
    `remarks`             VARCHAR(160)      NULL,
    `is_published`        TINYINT(1)        NOT NULL DEFAULT 0,
    `published_at`        TIMESTAMP         NULL DEFAULT NULL,
    `generated_at`        TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_results_student_term` (`student_id`, `exam_term_id`),
    -- Drives merit lists and position calculation
    KEY `idx_results_merit` (`exam_term_id`, `class_id`, `percentage`),
    KEY `idx_results_section` (`exam_term_id`, `section_id`, `percentage`),
    KEY `idx_results_published` (`is_published`, `exam_term_id`),
    CONSTRAINT `fk_results_student`    FOREIGN KEY (`student_id`)          REFERENCES `students` (`id`)            ON DELETE RESTRICT,
    CONSTRAINT `fk_results_enrollment` FOREIGN KEY (`enrollment_id`)       REFERENCES `student_enrollments` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_results_term`       FOREIGN KEY (`exam_term_id`)        REFERENCES `exam_terms` (`id`)          ON DELETE CASCADE,
    CONSTRAINT `fk_results_session`    FOREIGN KEY (`academic_session_id`) REFERENCES `academic_sessions` (`id`)   ON DELETE RESTRICT,
    CONSTRAINT `fk_results_class`      FOREIGN KEY (`class_id`)            REFERENCES `school_classes` (`id`)      ON DELETE RESTRICT,
    CONSTRAINT `fk_results_section`    FOREIGN KEY (`section_id`)          REFERENCES `sections` (`id`)            ON DELETE RESTRICT
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `exam_attendance` (
    `id`         BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `exam_id`    INT UNSIGNED    NOT NULL,
    `student_id` BIGINT UNSIGNED NOT NULL,
    `is_present` TINYINT(1)      NOT NULL DEFAULT 1,
    `remarks`    VARCHAR(160)    NULL,
    `marked_by`  BIGINT UNSIGNED NULL,
    `marked_at`  TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_exam_attendance` (`exam_id`, `student_id`),
    KEY `idx_exam_attendance_student` (`student_id`),
    CONSTRAINT `fk_exam_attendance_exam`      FOREIGN KEY (`exam_id`)    REFERENCES `exams` (`id`)    ON DELETE CASCADE,
    CONSTRAINT `fk_exam_attendance_student`   FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_exam_attendance_marked_by` FOREIGN KEY (`marked_by`)  REFERENCES `users` (`id`)    ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `datesheets` (
    `id`           BIGINT UNSIGNED   NOT NULL AUTO_INCREMENT,
    `exam_term_id` SMALLINT UNSIGNED NOT NULL,
    `class_id`     SMALLINT UNSIGNED NULL,
    `title`        VARCHAR(160)      NOT NULL,
    `file_path`    VARCHAR(255)      NULL,
    `notes`        TEXT              NULL,
    `is_published` TINYINT(1)        NOT NULL DEFAULT 0,
    `published_at` TIMESTAMP         NULL DEFAULT NULL,
    `created_by`   BIGINT UNSIGNED   NULL,
    `created_at`   TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_datesheets_term` (`exam_term_id`, `is_published`),
    CONSTRAINT `fk_datesheets_term`       FOREIGN KEY (`exam_term_id`) REFERENCES `exam_terms` (`id`)     ON DELETE CASCADE,
    CONSTRAINT `fk_datesheets_class`      FOREIGN KEY (`class_id`)     REFERENCES `school_classes` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_datesheets_created_by` FOREIGN KEY (`created_by`)   REFERENCES `users` (`id`)          ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
INSERT INTO `migrations` (`filename`, `batch`) VALUES ('0006_examination.sql', 1);

-- ============================== 0007_finance.sql ==============================

-- =============================================================================
-- 0007_finance.sql  ·  Domain G — Fees, challans, payments, expenses
-- -----------------------------------------------------------------------------
-- Every money column is DECIMAL(12,2). FLOAT/DOUBLE is never used: binary
-- floating point cannot represent 0.10 exactly, and rounding drift in a fee
-- ledger is not recoverable.
-- =============================================================================
USE `iiui_mardan`;
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE `fee_categories` (
    `id`            SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `name`          VARCHAR(80) NOT NULL COMMENT 'e.g. Tuition Fee',
    `code`          VARCHAR(20) NOT NULL,
    `type`          ENUM('recurring','one_time') NOT NULL DEFAULT 'recurring',
    `is_refundable` TINYINT(1)  NOT NULL DEFAULT 0,
    `description`   VARCHAR(255) NULL,
    `sort_order`    SMALLINT    NOT NULL DEFAULT 0,
    `is_active`     TINYINT(1)  NOT NULL DEFAULT 1,
    `created_at`    TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`    TIMESTAMP   NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_fee_categories_code` (`code`),
    KEY `idx_fee_categories_active` (`is_active`, `sort_order`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- fee_structures — what a class owes, per session. Fee policy is DATA:
-- changing next year's tuition is a row update, never a deployment.
CREATE TABLE `fee_structures` (
    `id`                  INT UNSIGNED      NOT NULL AUTO_INCREMENT,
    `academic_session_id` SMALLINT UNSIGNED NOT NULL,
    `class_id`            SMALLINT UNSIGNED NOT NULL,
    `stream_id`           TINYINT UNSIGNED  NULL,
    `fee_category_id`     SMALLINT UNSIGNED NOT NULL,
    `amount`              DECIMAL(12,2)     NOT NULL,
    `frequency`           ENUM('monthly','quarterly','bi_annual','annual','one_time') NOT NULL DEFAULT 'monthly',
    `due_day`             TINYINT UNSIGNED  NOT NULL DEFAULT 10,
    `applies_to`          ENUM('all','new','existing') NOT NULL DEFAULT 'all',
    `is_active`           TINYINT(1)        NOT NULL DEFAULT 1,
    `created_by`          BIGINT UNSIGNED   NULL,
    `created_at`          TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`          TIMESTAMP         NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_fee_structures_unique` (`academic_session_id`, `class_id`, `stream_id`, `fee_category_id`),
    KEY `idx_fee_structures_lookup` (`academic_session_id`, `class_id`, `is_active`),
    CONSTRAINT `chk_fee_structures_amount`  CHECK (`amount` >= 0),
    CONSTRAINT `chk_fee_structures_due_day` CHECK (`due_day` BETWEEN 1 AND 28),
    CONSTRAINT `fk_fee_structures_session`  FOREIGN KEY (`academic_session_id`) REFERENCES `academic_sessions` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_fee_structures_class`    FOREIGN KEY (`class_id`)            REFERENCES `school_classes` (`id`)    ON DELETE CASCADE,
    CONSTRAINT `fk_fee_structures_stream`   FOREIGN KEY (`stream_id`)           REFERENCES `streams` (`id`)           ON DELETE CASCADE,
    CONSTRAINT `fk_fee_structures_category` FOREIGN KEY (`fee_category_id`)     REFERENCES `fee_categories` (`id`)    ON DELETE RESTRICT,
    CONSTRAINT `fk_fee_structures_created_by` FOREIGN KEY (`created_by`)        REFERENCES `users` (`id`)             ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `student_fee_discounts` (
    `id`                  INT UNSIGNED      NOT NULL AUTO_INCREMENT,
    `student_id`          BIGINT UNSIGNED   NOT NULL,
    `academic_session_id` SMALLINT UNSIGNED NOT NULL,
    `fee_category_id`     SMALLINT UNSIGNED NULL COMMENT 'NULL = applies to every category',
    `type`                ENUM('percentage','fixed') NOT NULL DEFAULT 'percentage',
    `value`               DECIMAL(10,2)     NOT NULL,
    `reason`              ENUM('sibling','merit','staff_child','hardship','orphan','sports','other') NOT NULL DEFAULT 'other',
    `valid_from`          DATE              NULL,
    `valid_to`            DATE              NULL,
    `approved_by`         BIGINT UNSIGNED   NULL,
    `approved_at`         TIMESTAMP         NULL DEFAULT NULL,
    `remarks`             VARCHAR(255)      NULL,
    `is_active`           TINYINT(1)        NOT NULL DEFAULT 1,
    `created_at`          TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`          TIMESTAMP         NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_discounts_student_category` (`student_id`, `academic_session_id`, `fee_category_id`),
    KEY `idx_discounts_session_active` (`academic_session_id`, `is_active`),
    CONSTRAINT `chk_discounts_value` CHECK (`value` >= 0 AND (`type` = 'fixed' OR `value` <= 100)),
    CONSTRAINT `fk_discounts_student`  FOREIGN KEY (`student_id`)          REFERENCES `students` (`id`)          ON DELETE CASCADE,
    CONSTRAINT `fk_discounts_session`  FOREIGN KEY (`academic_session_id`) REFERENCES `academic_sessions` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_discounts_category` FOREIGN KEY (`fee_category_id`)     REFERENCES `fee_categories` (`id`)    ON DELETE CASCADE,
    CONSTRAINT `fk_discounts_approved_by` FOREIGN KEY (`approved_by`)      REFERENCES `users` (`id`)             ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- fee_challans — the invoice. `balance_amount` is a STORED generated column so
-- it can never disagree with payable minus paid; there is no code path that can
-- set it wrongly.
-- -----------------------------------------------------------------------------
CREATE TABLE `fee_challans` (
    `challan_no`          VARCHAR(30)       NOT NULL,
    `id`                  BIGINT UNSIGNED   NOT NULL AUTO_INCREMENT,
    `student_id`          BIGINT UNSIGNED   NOT NULL,
    `enrollment_id`       BIGINT UNSIGNED   NOT NULL,
    `academic_session_id` SMALLINT UNSIGNED NOT NULL,
    `class_id`            SMALLINT UNSIGNED NOT NULL,
    `section_id`          SMALLINT UNSIGNED NOT NULL,
    `billing_month`       TINYINT UNSIGNED  NULL COMMENT 'NULL for one-time challans',
    `billing_year`        SMALLINT UNSIGNED NOT NULL,
    `issue_date`          DATE              NOT NULL,
    `due_date`            DATE              NOT NULL,
    `gross_amount`        DECIMAL(12,2)     NOT NULL DEFAULT 0.00,
    `discount_amount`     DECIMAL(12,2)     NOT NULL DEFAULT 0.00,
    `fine_amount`         DECIMAL(12,2)     NOT NULL DEFAULT 0.00,
    `payable_amount`      DECIMAL(12,2)     NOT NULL DEFAULT 0.00,
    `paid_amount`         DECIMAL(12,2)     NOT NULL DEFAULT 0.00,
    `balance_amount`      DECIMAL(12,2)     GENERATED ALWAYS AS (`payable_amount` - `paid_amount`) STORED,
    `status`              ENUM('unpaid','partial','paid','overdue','cancelled') NOT NULL DEFAULT 'unpaid',
    `generated_by`        BIGINT UNSIGNED   NULL,
    `batch_ref`           CHAR(36)          NULL COMMENT 'groups one bulk generation run',
    `cancelled_by`        BIGINT UNSIGNED   NULL,
    `cancelled_at`        TIMESTAMP         NULL DEFAULT NULL,
    `cancel_reason`       VARCHAR(255)      NULL,
    `notes`               VARCHAR(255)      NULL,
    `created_at`          TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`          TIMESTAMP         NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,

    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_challans_no` (`challan_no`),
    -- One challan per student per billing period; blocks double-generation.
    UNIQUE KEY `uq_challans_student_period` (`student_id`, `academic_session_id`, `billing_year`, `billing_month`),

    KEY `idx_challans_student_status` (`student_id`, `status`),
    KEY `idx_challans_overdue`        (`status`, `due_date`),
    KEY `idx_challans_period`         (`academic_session_id`, `billing_year`, `billing_month`, `status`),
    KEY `idx_challans_class`          (`class_id`, `section_id`, `status`),
    KEY `idx_challans_batch`          (`batch_ref`),

    CONSTRAINT `chk_challans_month`   CHECK (`billing_month` IS NULL OR `billing_month` BETWEEN 1 AND 12),
    CONSTRAINT `chk_challans_amounts` CHECK (`gross_amount` >= 0 AND `discount_amount` >= 0 AND `fine_amount` >= 0 AND `paid_amount` >= 0),
    CONSTRAINT `chk_challans_due`     CHECK (`due_date` >= `issue_date`),

    CONSTRAINT `fk_challans_student`    FOREIGN KEY (`student_id`)          REFERENCES `students` (`id`)            ON DELETE RESTRICT,
    CONSTRAINT `fk_challans_enrollment` FOREIGN KEY (`enrollment_id`)       REFERENCES `student_enrollments` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_challans_session`    FOREIGN KEY (`academic_session_id`) REFERENCES `academic_sessions` (`id`)   ON DELETE RESTRICT,
    CONSTRAINT `fk_challans_class`      FOREIGN KEY (`class_id`)            REFERENCES `school_classes` (`id`)      ON DELETE RESTRICT,
    CONSTRAINT `fk_challans_section`    FOREIGN KEY (`section_id`)          REFERENCES `sections` (`id`)            ON DELETE RESTRICT,
    CONSTRAINT `fk_challans_generated_by` FOREIGN KEY (`generated_by`)      REFERENCES `users` (`id`)               ON DELETE SET NULL,
    CONSTRAINT `fk_challans_cancelled_by` FOREIGN KEY (`cancelled_by`)      REFERENCES `users` (`id`)               ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- A challan is never a single opaque number — it always itemizes.
CREATE TABLE `fee_challan_items` (
    `id`              BIGINT UNSIGNED   NOT NULL AUTO_INCREMENT,
    `challan_id`      BIGINT UNSIGNED   NOT NULL,
    `fee_category_id` SMALLINT UNSIGNED NOT NULL,
    `description`     VARCHAR(160)      NULL,
    `amount`          DECIMAL(12,2)     NOT NULL DEFAULT 0.00,
    `discount`        DECIMAL(12,2)     NOT NULL DEFAULT 0.00,
    `net_amount`      DECIMAL(12,2)     GENERATED ALWAYS AS (`amount` - `discount`) STORED,
    `sort_order`      SMALLINT          NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_challan_items_category` (`challan_id`, `fee_category_id`),
    KEY `idx_challan_items_category` (`fee_category_id`),
    CONSTRAINT `chk_challan_items_amounts` CHECK (`amount` >= 0 AND `discount` >= 0 AND `discount` <= `amount`),
    CONSTRAINT `fk_challan_items_challan`  FOREIGN KEY (`challan_id`)      REFERENCES `fee_challans` (`id`)   ON DELETE CASCADE,
    CONSTRAINT `fk_challan_items_category` FOREIGN KEY (`fee_category_id`) REFERENCES `fee_categories` (`id`) ON DELETE RESTRICT
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- fee_payments — APPEND-ONLY. A correction is a new row with a negative amount
-- referencing `reverses_payment_id`, never an UPDATE of history. This is what
-- makes the ledger auditable: the sum of rows always equals what was banked.
-- -----------------------------------------------------------------------------
CREATE TABLE `fee_payments` (
    `id`                  BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `receipt_no`          VARCHAR(30)     NOT NULL,
    `challan_id`          BIGINT UNSIGNED NOT NULL,
    `student_id`          BIGINT UNSIGNED NOT NULL,
    `amount`              DECIMAL(12,2)   NOT NULL COMMENT 'negative on a reversal row',
    `payment_date`        DATE            NOT NULL,
    `method`              ENUM('cash','bank_deposit','cheque','online','card','adjustment') NOT NULL DEFAULT 'cash',
    `bank_name`           VARCHAR(80)     NULL,
    `transaction_ref`     VARCHAR(80)     NULL,
    `cheque_no`           VARCHAR(40)     NULL,
    `cheque_date`         DATE            NULL,
    `status`              ENUM('pending','cleared','bounced','reversed') NOT NULL DEFAULT 'cleared',
    `reverses_payment_id` BIGINT UNSIGNED NULL,
    `reversal_reason`     VARCHAR(255)    NULL,
    `received_by`         BIGINT UNSIGNED NULL,
    `verified_by`         BIGINT UNSIGNED NULL,
    `remarks`             VARCHAR(255)    NULL,
    `attachment`          VARCHAR(255)    NULL,
    `created_at`          TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`          TIMESTAMP       NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_payments_receipt` (`receipt_no`),
    UNIQUE KEY `uq_payments_reversal` (`reverses_payment_id`),
    KEY `idx_payments_challan`  (`challan_id`),
    KEY `idx_payments_student`  (`student_id`, `payment_date`),
    -- Daily collection report
    KEY `idx_payments_daily`    (`payment_date`, `status`),
    KEY `idx_payments_method`   (`method`, `payment_date`),
    KEY `idx_payments_received_by` (`received_by`, `payment_date`),
    CONSTRAINT `chk_payments_amount_nonzero` CHECK (`amount` <> 0),
    CONSTRAINT `fk_payments_challan`     FOREIGN KEY (`challan_id`)          REFERENCES `fee_challans` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_payments_student`     FOREIGN KEY (`student_id`)          REFERENCES `students` (`id`)     ON DELETE RESTRICT,
    CONSTRAINT `fk_payments_reverses`    FOREIGN KEY (`reverses_payment_id`) REFERENCES `fee_payments` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_payments_received_by` FOREIGN KEY (`received_by`)         REFERENCES `users` (`id`)        ON DELETE SET NULL,
    CONSTRAINT `fk_payments_verified_by` FOREIGN KEY (`verified_by`)         REFERENCES `users` (`id`)        ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `fee_fines` (
    `id`           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `challan_id`   BIGINT UNSIGNED NOT NULL,
    `rule`         ENUM('fixed','per_day','percentage') NOT NULL DEFAULT 'fixed',
    `rate`         DECIMAL(10,2)   NOT NULL DEFAULT 0.00,
    `days_late`    SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    `amount`       DECIMAL(12,2)   NOT NULL DEFAULT 0.00,
    `applied_on`   DATE            NOT NULL,
    `is_waived`    TINYINT(1)      NOT NULL DEFAULT 0,
    `waived_by`    BIGINT UNSIGNED NULL,
    `waived_at`    TIMESTAMP       NULL DEFAULT NULL,
    `waive_reason` VARCHAR(255)    NULL,
    `created_at`   TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_fines_challan_date` (`challan_id`, `applied_on`),
    KEY `idx_fines_waived` (`is_waived`, `applied_on`),
    CONSTRAINT `chk_fines_amount` CHECK (`amount` >= 0),
    CONSTRAINT `fk_fines_challan`   FOREIGN KEY (`challan_id`) REFERENCES `fee_challans` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_fines_waived_by` FOREIGN KEY (`waived_by`)  REFERENCES `users` (`id`)        ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `expense_categories` (
    `id`        SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `name`      VARCHAR(80) NOT NULL,
    `code`      VARCHAR(20) NOT NULL,
    `is_active` TINYINT(1)  NOT NULL DEFAULT 1,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_expense_categories_code` (`code`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `expenses` (
    `id`                  BIGINT UNSIGNED   NOT NULL AUTO_INCREMENT,
    `voucher_no`          VARCHAR(30)       NOT NULL,
    `expense_category_id` SMALLINT UNSIGNED NOT NULL,
    `academic_session_id` SMALLINT UNSIGNED NOT NULL,
    `title`               VARCHAR(160)      NOT NULL,
    `description`         TEXT              NULL,
    `amount`              DECIMAL(12,2)     NOT NULL,
    `expense_date`        DATE              NOT NULL,
    `paid_to`             VARCHAR(160)      NULL,
    `payment_method`      ENUM('cash','bank_transfer','cheque','online') NOT NULL DEFAULT 'cash',
    `reference_no`        VARCHAR(80)       NULL,
    `attachment`          VARCHAR(255)      NULL,
    `status`              ENUM('pending','approved','paid','rejected') NOT NULL DEFAULT 'pending',
    `requested_by`        BIGINT UNSIGNED   NULL,
    `approved_by`         BIGINT UNSIGNED   NULL,
    `approved_at`         TIMESTAMP         NULL DEFAULT NULL,
    `created_at`          TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`          TIMESTAMP         NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_expenses_voucher` (`voucher_no`),
    KEY `idx_expenses_date_status` (`expense_date`, `status`),
    KEY `idx_expenses_category`    (`expense_category_id`, `expense_date`),
    KEY `idx_expenses_session`     (`academic_session_id`, `status`),
    CONSTRAINT `chk_expenses_amount` CHECK (`amount` > 0),
    CONSTRAINT `fk_expenses_category`     FOREIGN KEY (`expense_category_id`) REFERENCES `expense_categories` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_expenses_session`      FOREIGN KEY (`academic_session_id`) REFERENCES `academic_sessions` (`id`)  ON DELETE RESTRICT,
    CONSTRAINT `fk_expenses_requested_by` FOREIGN KEY (`requested_by`)        REFERENCES `users` (`id`)              ON DELETE SET NULL,
    CONSTRAINT `fk_expenses_approved_by`  FOREIGN KEY (`approved_by`)         REFERENCES `users` (`id`)              ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- transactions — a unified ledger written by triggers on payments/expenses.
-- The finance dashboard reads one indexed table instead of UNION-ing three
-- at query time.
CREATE TABLE `transactions` (
    `id`                  BIGINT UNSIGNED   NOT NULL AUTO_INCREMENT,
    `type`                ENUM('income','expense') NOT NULL,
    `source_type`         ENUM('fee_payment','expense','payroll','other') NOT NULL,
    `source_id`           BIGINT UNSIGNED   NOT NULL,
    `academic_session_id` SMALLINT UNSIGNED NULL,
    `amount`              DECIMAL(12,2)     NOT NULL,
    `transaction_date`    DATE              NOT NULL,
    `category`            VARCHAR(80)       NULL,
    `description`         VARCHAR(255)      NULL,
    `created_at`          TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_transactions_source` (`source_type`, `source_id`),
    KEY `idx_transactions_date_type` (`transaction_date`, `type`),
    KEY `idx_transactions_session`   (`academic_session_id`, `type`, `transaction_date`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
INSERT INTO `migrations` (`filename`, `batch`) VALUES ('0007_finance.sql', 1);

-- ============================== 0008_cms.sql ==============================

-- =============================================================================
-- 0008_cms.sql  ·  Domain H — Website content, media, menus, SEO
-- =============================================================================
USE `iiui_mardan`;
SET FOREIGN_KEY_CHECKS = 0;

-- pages — `is_system = 1` on Home/About/Contact stops an editor deleting a page
-- the router depends on.
CREATE TABLE `pages` (
    `id`               BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `parent_id`        BIGINT UNSIGNED NULL,
    `title`            VARCHAR(180)    NOT NULL,
    `slug`             VARCHAR(200)    NOT NULL,
    `excerpt`          VARCHAR(500)    NULL,
    `content`          LONGTEXT        NULL,
    `featured_image`   VARCHAR(255)    NULL,
    `template`         VARCHAR(60)     NOT NULL DEFAULT 'default',
    `meta_title`       VARCHAR(180)    NULL,
    `meta_description` VARCHAR(300)    NULL,
    `meta_keywords`    VARCHAR(255)    NULL,
    `og_image`         VARCHAR(255)    NULL,
    `canonical_url`    VARCHAR(255)    NULL,
    `sort_order`       SMALLINT        NOT NULL DEFAULT 0,
    `is_system`        TINYINT(1)      NOT NULL DEFAULT 0,
    `show_in_menu`     TINYINT(1)      NOT NULL DEFAULT 0,
    `status`           ENUM('draft','published','scheduled','archived') NOT NULL DEFAULT 'draft',
    `published_at`     TIMESTAMP       NULL DEFAULT NULL,
    `author_id`        BIGINT UNSIGNED NULL,
    `views`            INT UNSIGNED    NOT NULL DEFAULT 0,
    `created_at`       TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`       TIMESTAMP       NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    `deleted_at`       TIMESTAMP       NULL DEFAULT NULL,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_pages_slug` (`slug`),
    KEY `idx_pages_status_published` (`status`, `published_at`),
    KEY `idx_pages_parent` (`parent_id`, `sort_order`),
    FULLTEXT KEY `ftx_pages_content` (`title`, `excerpt`, `content`),
    CONSTRAINT `fk_pages_parent` FOREIGN KEY (`parent_id`) REFERENCES `pages` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_pages_author` FOREIGN KEY (`author_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `post_categories` (
    `id`          SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `parent_id`   SMALLINT UNSIGNED NULL,
    `name`        VARCHAR(100) NOT NULL,
    `slug`        VARCHAR(120) NOT NULL,
    `description` VARCHAR(255) NULL,
    `sort_order`  SMALLINT     NOT NULL DEFAULT 0,
    `is_active`   TINYINT(1)   NOT NULL DEFAULT 1,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_post_categories_slug` (`slug`),
    KEY `idx_post_categories_parent` (`parent_id`),
    CONSTRAINT `fk_post_categories_parent` FOREIGN KEY (`parent_id`) REFERENCES `post_categories` (`id`) ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `posts` (
    `id`               BIGINT UNSIGNED   NOT NULL AUTO_INCREMENT,
    `category_id`      SMALLINT UNSIGNED NULL,
    `title`            VARCHAR(180)      NOT NULL,
    `slug`             VARCHAR(200)      NOT NULL,
    `excerpt`          VARCHAR(500)      NULL,
    `content`          LONGTEXT          NULL,
    `featured_image`   VARCHAR(255)      NULL,
    `gallery`          JSON              NULL,
    `meta_title`       VARCHAR(180)      NULL,
    `meta_description` VARCHAR(300)      NULL,
    `og_image`         VARCHAR(255)      NULL,
    `status`           ENUM('draft','published','scheduled','archived') NOT NULL DEFAULT 'draft',
    `is_featured`      TINYINT(1)        NOT NULL DEFAULT 0,
    `is_pinned`        TINYINT(1)        NOT NULL DEFAULT 0,
    `views`            INT UNSIGNED      NOT NULL DEFAULT 0,
    `published_at`     TIMESTAMP         NULL DEFAULT NULL,
    `author_id`        BIGINT UNSIGNED   NULL,
    `created_at`       TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`       TIMESTAMP         NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    `deleted_at`       TIMESTAMP         NULL DEFAULT NULL,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_posts_slug` (`slug`),
    -- The public news listing: status + date, newest first.
    KEY `idx_posts_listing`  (`status`, `published_at`),
    KEY `idx_posts_category` (`category_id`, `status`, `published_at`),
    KEY `idx_posts_featured` (`is_featured`, `status`, `published_at`),
    FULLTEXT KEY `ftx_posts_content` (`title`, `excerpt`, `content`),
    CONSTRAINT `fk_posts_category` FOREIGN KEY (`category_id`) REFERENCES `post_categories` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_posts_author`   FOREIGN KEY (`author_id`)   REFERENCES `users` (`id`)           ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `tags` (
    `id`   SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `name` VARCHAR(60)  NOT NULL,
    `slug` VARCHAR(80)  NOT NULL,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_tags_slug` (`slug`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `post_tags` (
    `post_id` BIGINT UNSIGNED   NOT NULL,
    `tag_id`  SMALLINT UNSIGNED NOT NULL,
    PRIMARY KEY (`post_id`, `tag_id`),
    KEY `idx_post_tags_tag` (`tag_id`),
    CONSTRAINT `fk_post_tags_post` FOREIGN KEY (`post_id`) REFERENCES `posts` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_post_tags_tag`  FOREIGN KEY (`tag_id`)  REFERENCES `tags` (`id`)  ON DELETE CASCADE
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `events` (
    `id`                    BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `title`                 VARCHAR(180)    NOT NULL,
    `slug`                  VARCHAR(200)    NOT NULL,
    `description`           VARCHAR(500)    NULL,
    `content`               LONGTEXT        NULL,
    `banner`                VARCHAR(255)    NULL,
    `start_datetime`        DATETIME        NOT NULL,
    `end_datetime`          DATETIME        NULL,
    `venue`                 VARCHAR(180)    NULL,
    `organizer`             VARCHAR(120)    NULL,
    `category`              VARCHAR(60)     NULL,
    `registration_required` TINYINT(1)      NOT NULL DEFAULT 0,
    `registration_url`      VARCHAR(255)    NULL,
    `capacity`              SMALLINT UNSIGNED NULL,
    `is_featured`           TINYINT(1)      NOT NULL DEFAULT 0,
    `status`                ENUM('draft','published','cancelled','completed') NOT NULL DEFAULT 'draft',
    `meta_title`            VARCHAR(180)    NULL,
    `meta_description`      VARCHAR(300)    NULL,
    `author_id`             BIGINT UNSIGNED NULL,
    `created_at`            TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`            TIMESTAMP       NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    `deleted_at`            TIMESTAMP       NULL DEFAULT NULL,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_events_slug` (`slug`),
    KEY `idx_events_schedule` (`status`, `start_datetime`),
    KEY `idx_events_featured` (`is_featured`, `start_datetime`),
    CONSTRAINT `chk_events_range` CHECK (`end_datetime` IS NULL OR `end_datetime` >= `start_datetime`),
    CONSTRAINT `fk_events_author` FOREIGN KEY (`author_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `notices` (
    `id`           BIGINT UNSIGNED   NOT NULL AUTO_INCREMENT,
    `title`        VARCHAR(180)      NOT NULL,
    `slug`         VARCHAR(200)      NOT NULL,
    `content`      LONGTEXT          NULL,
    `attachment`   VARCHAR(255)      NULL,
    `audience`     ENUM('all','students','parents','staff','specific_class') NOT NULL DEFAULT 'all',
    `class_id`     SMALLINT UNSIGNED NULL,
    `priority`     ENUM('low','normal','high','urgent') NOT NULL DEFAULT 'normal',
    `publish_from` DATETIME          NOT NULL,
    `publish_to`   DATETIME          NULL,
    `is_pinned`    TINYINT(1)        NOT NULL DEFAULT 0,
    `status`       ENUM('draft','published','archived') NOT NULL DEFAULT 'draft',
    `views`        INT UNSIGNED      NOT NULL DEFAULT 0,
    `author_id`    BIGINT UNSIGNED   NULL,
    `created_at`   TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`   TIMESTAMP         NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    `deleted_at`   TIMESTAMP         NULL DEFAULT NULL,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_notices_slug` (`slug`),
    -- "What should this audience see right now?"
    KEY `idx_notices_window`   (`status`, `publish_from`, `publish_to`),
    KEY `idx_notices_audience` (`audience`, `class_id`, `status`),
    KEY `idx_notices_priority` (`is_pinned`, `priority`, `publish_from`),
    CONSTRAINT `chk_notices_window` CHECK (`publish_to` IS NULL OR `publish_to` >= `publish_from`),
    CONSTRAINT `fk_notices_class`  FOREIGN KEY (`class_id`)  REFERENCES `school_classes` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_notices_author` FOREIGN KEY (`author_id`) REFERENCES `users` (`id`)          ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `galleries` (
    `id`           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `title`        VARCHAR(180)    NOT NULL,
    `slug`         VARCHAR(200)    NOT NULL,
    `description`  VARCHAR(500)    NULL,
    `cover_image`  VARCHAR(255)    NULL,
    `event_id`     BIGINT UNSIGNED NULL,
    `gallery_date` DATE            NULL,
    `category`     VARCHAR(60)     NULL,
    `status`       ENUM('draft','published','archived') NOT NULL DEFAULT 'draft',
    `sort_order`   SMALLINT        NOT NULL DEFAULT 0,
    `created_by`   BIGINT UNSIGNED NULL,
    `created_at`   TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`   TIMESTAMP       NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_galleries_slug` (`slug`),
    KEY `idx_galleries_status` (`status`, `gallery_date`),
    CONSTRAINT `fk_galleries_event`      FOREIGN KEY (`event_id`)   REFERENCES `events` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_galleries_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`)  ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `gallery_images` (
    `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `gallery_id`     BIGINT UNSIGNED NOT NULL,
    `image_path`     VARCHAR(255)    NOT NULL,
    `thumbnail_path` VARCHAR(255)    NULL,
    `caption`        VARCHAR(255)    NULL,
    `alt_text`       VARCHAR(180)    NULL,
    `sort_order`     SMALLINT        NOT NULL DEFAULT 0,
    `created_at`     TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_gallery_images_gallery` (`gallery_id`, `sort_order`),
    CONSTRAINT `fk_gallery_images_gallery` FOREIGN KEY (`gallery_id`) REFERENCES `galleries` (`id`) ON DELETE CASCADE
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `sliders` (
    `id`              SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `title`           VARCHAR(180)  NOT NULL,
    `subtitle`        VARCHAR(255)  NULL,
    `description`     VARCHAR(500)  NULL,
    `image`           VARCHAR(255)  NOT NULL,
    `mobile_image`    VARCHAR(255)  NULL,
    `button_text`     VARCHAR(60)   NULL,
    `button_url`      VARCHAR(255)  NULL,
    `text_position`   ENUM('left','center','right') NOT NULL DEFAULT 'left',
    `overlay_opacity` TINYINT UNSIGNED NOT NULL DEFAULT 70,
    `sort_order`      SMALLINT      NOT NULL DEFAULT 0,
    `is_active`       TINYINT(1)    NOT NULL DEFAULT 1,
    `starts_at`       DATETIME      NULL,
    `ends_at`         DATETIME      NULL,
    `created_at`      TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`      TIMESTAMP     NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_sliders_active` (`is_active`, `sort_order`),
    CONSTRAINT `chk_sliders_opacity` CHECK (`overlay_opacity` BETWEEN 0 AND 100)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `downloads` (
    `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `title`          VARCHAR(180)    NOT NULL,
    `description`    VARCHAR(500)    NULL,
    `category`       VARCHAR(60)     NULL,
    `file_path`      VARCHAR(255)    NOT NULL,
    `file_name`      VARCHAR(180)    NOT NULL,
    `file_size`      INT UNSIGNED    NOT NULL,
    `mime_type`      VARCHAR(100)    NOT NULL,
    `audience`       ENUM('public','students','parents','staff') NOT NULL DEFAULT 'public',
    `download_count` INT UNSIGNED    NOT NULL DEFAULT 0,
    `is_active`      TINYINT(1)      NOT NULL DEFAULT 1,
    `uploaded_by`    BIGINT UNSIGNED NULL,
    `created_at`     TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`     TIMESTAMP       NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_downloads_audience` (`audience`, `is_active`, `category`),
    CONSTRAINT `fk_downloads_uploaded_by` FOREIGN KEY (`uploaded_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `menus` (
    `id`        TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `name`      VARCHAR(80) NOT NULL,
    `location`  ENUM('header','footer','quick_links','sidebar','mobile') NOT NULL,
    `is_active` TINYINT(1)  NOT NULL DEFAULT 1,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_menus_location` (`location`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `menu_items` (
    `id`           SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `menu_id`      TINYINT UNSIGNED  NOT NULL,
    `parent_id`    SMALLINT UNSIGNED NULL,
    `title`        VARCHAR(100)      NOT NULL,
    `type`         ENUM('page','post','category','custom','module') NOT NULL DEFAULT 'custom',
    `reference_id` BIGINT UNSIGNED   NULL,
    `url`          VARCHAR(255)      NULL,
    `icon`         VARCHAR(60)       NULL,
    `target`       ENUM('_self','_blank') NOT NULL DEFAULT '_self',
    `description`  VARCHAR(180)      NULL COMMENT 'shown in the mega menu',
    `sort_order`   SMALLINT          NOT NULL DEFAULT 0,
    `is_active`    TINYINT(1)        NOT NULL DEFAULT 1,
    PRIMARY KEY (`id`),
    KEY `idx_menu_items_tree` (`menu_id`, `parent_id`, `sort_order`),
    CONSTRAINT `fk_menu_items_menu`   FOREIGN KEY (`menu_id`)   REFERENCES `menus` (`id`)      ON DELETE CASCADE,
    CONSTRAINT `fk_menu_items_parent` FOREIGN KEY (`parent_id`) REFERENCES `menu_items` (`id`) ON DELETE CASCADE
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- media — the shared library. `disk` is the seam for moving to S3-compatible
-- object storage later without touching a single call site.
CREATE TABLE `media` (
    `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `uuid`           CHAR(36)        NOT NULL,
    `filename`       VARCHAR(180)    NOT NULL,
    `original_name`  VARCHAR(255)    NOT NULL,
    `path`           VARCHAR(255)    NOT NULL,
    `thumbnail_path` VARCHAR(255)    NULL,
    `disk`           VARCHAR(30)     NOT NULL DEFAULT 'local',
    `mime_type`      VARCHAR(100)    NOT NULL,
    `extension`      VARCHAR(10)     NOT NULL,
    `size_bytes`     INT UNSIGNED    NOT NULL,
    `width`          SMALLINT UNSIGNED NULL,
    `height`         SMALLINT UNSIGNED NULL,
    `folder`         VARCHAR(120)    NOT NULL DEFAULT 'uploads',
    `alt_text`       VARCHAR(180)    NULL,
    `caption`        VARCHAR(255)    NULL,
    `entity_type`    VARCHAR(60)     NULL,
    `entity_id`      BIGINT UNSIGNED NULL,
    `uploaded_by`    BIGINT UNSIGNED NULL,
    `created_at`     TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_media_uuid` (`uuid`),
    KEY `idx_media_folder` (`folder`, `created_at`),
    KEY `idx_media_entity` (`entity_type`, `entity_id`),
    KEY `idx_media_mime`   (`mime_type`),
    CONSTRAINT `fk_media_uploaded_by` FOREIGN KEY (`uploaded_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `settings` (
    `id`          SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `group_name`  VARCHAR(40)  NOT NULL,
    `key_name`    VARCHAR(80)  NOT NULL,
    `value`       TEXT         NULL,
    `type`        ENUM('text','textarea','number','boolean','image','file','json','select','color','email','url') NOT NULL DEFAULT 'text',
    `options`     JSON         NULL,
    `label`       VARCHAR(120) NOT NULL,
    `description` VARCHAR(255) NULL,
    `is_public`   TINYINT(1)   NOT NULL DEFAULT 0,
    `sort_order`  SMALLINT     NOT NULL DEFAULT 0,
    `updated_by`  BIGINT UNSIGNED NULL,
    `updated_at`  TIMESTAMP    NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_settings_key` (`key_name`),
    KEY `idx_settings_group` (`group_name`, `sort_order`),
    CONSTRAINT `fk_settings_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `faqs` (
    `id`         SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `question`   VARCHAR(300) NOT NULL,
    `answer`     TEXT         NOT NULL,
    `category`   VARCHAR(60)  NULL,
    `sort_order` SMALLINT     NOT NULL DEFAULT 0,
    `is_active`  TINYINT(1)   NOT NULL DEFAULT 1,
    PRIMARY KEY (`id`),
    KEY `idx_faqs_category` (`category`, `is_active`, `sort_order`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `testimonials` (
    `id`          SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `name`        VARCHAR(120) NOT NULL,
    `designation` VARCHAR(120) NULL,
    `photo`       VARCHAR(255) NULL,
    `content`     TEXT         NOT NULL,
    `rating`      TINYINT UNSIGNED NULL,
    `type`        ENUM('student','parent','alumni','staff') NOT NULL DEFAULT 'parent',
    `is_featured` TINYINT(1)   NOT NULL DEFAULT 0,
    `status`      ENUM('draft','published') NOT NULL DEFAULT 'draft',
    `sort_order`  SMALLINT     NOT NULL DEFAULT 0,
    `created_at`  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_testimonials_status` (`status`, `is_featured`, `sort_order`),
    CONSTRAINT `chk_testimonials_rating` CHECK (`rating` IS NULL OR `rating` BETWEEN 1 AND 5)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

CREATE TABLE `contact_messages` (
    `id`            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `name`          VARCHAR(120)    NOT NULL,
    `email`         VARCHAR(191)    NOT NULL,
    `phone`         VARCHAR(20)     NULL,
    `subject`       VARCHAR(180)    NULL,
    `message`       TEXT            NOT NULL,
    `ip_address`    VARBINARY(16)   NULL,
    `user_agent`    VARCHAR(255)    NULL,
    `status`        ENUM('new','read','replied','spam','archived') NOT NULL DEFAULT 'new',
    `replied_by`    BIGINT UNSIGNED NULL,
    `replied_at`    TIMESTAMP       NULL DEFAULT NULL,
    `reply_message` TEXT            NULL,
    `created_at`    TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_contact_status` (`status`, `created_at`),
    KEY `idx_contact_email`  (`email`),
    CONSTRAINT `fk_contact_replied_by` FOREIGN KEY (`replied_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- seo_redirects — a changed slug writes a 301 here automatically, so links from
-- Facebook posts and printed prospectuses keep working.
CREATE TABLE `seo_redirects` (
    `id`          INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `from_path`   VARCHAR(255) NOT NULL,
    `to_path`     VARCHAR(255) NOT NULL,
    `status_code` SMALLINT UNSIGNED NOT NULL DEFAULT 301,
    `hits`        INT UNSIGNED NOT NULL DEFAULT 0,
    `is_active`   TINYINT(1)   NOT NULL DEFAULT 1,
    `created_at`  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_redirects_from` (`from_path`),
    CONSTRAINT `chk_redirects_code` CHECK (`status_code` IN (301, 302, 307, 308))
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- page_views — lightweight in-house analytics. Pruned monthly by cron; the
-- IP is stored hashed, never in the clear.
CREATE TABLE `page_views` (
    `id`          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `url`         VARCHAR(255)    NOT NULL,
    `entity_type` VARCHAR(60)     NULL,
    `entity_id`   BIGINT UNSIGNED NULL,
    `ip_hash`     CHAR(64)        NULL,
    `referrer`    VARCHAR(255)    NULL,
    `user_agent`  VARCHAR(255)    NULL,
    `viewed_at`   TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_page_views_entity` (`entity_type`, `entity_id`, `viewed_at`),
    KEY `idx_page_views_date`   (`viewed_at`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

